var e={"is-14-7":{e:`quranenc-korean-hamid`,t:[`너희 주님께서 알려 주는 것 을 상기할지니 만일 너희가 감사 한다면 내가 너희에게 더할 것이 며 너희가 감사하지 않을때 실 로 나의 벌이 무서우리라`]},"is-2-152":{e:`quranenc-korean-rwwad`,t:[`그러니 그대들은 나를 기억하라, 내가 그대들을 기억할 것이라. 그리고 나에게 감사하며 나를 불신하지 말라.`]},"is-31-12":{e:`quranenc-korean-hamid`,t:[`하나님은 루끄만에게 지혜를주며 하나님께 감사드리라 했거늘 감사를 드리는 자는 곧 자기 자신 을 위한 것이며 감사할 줄 모르는 자가 있다면 실로 하나님께서는 자족하시며 은혜로우시니라`]},"is-27-19":{e:`quranenc-korean-hamid`,t:[`솔로몬은 개미의 말에 웃음 을 터트리며 말하길 주여 저와 저 의 부모에게 베풀어 준 당시의 은혜에 감사하도록 허용하여 주소서당신께서 저로 하여금 기뻐하는 선행을 하도록 하여 주소서 당신 의 은혜로서 당신의 성실한 종들 중의 한 종이 되게 하소서`]},"is-16-18":{e:`quranenc-korean-hamid`,t:[`너희가 하나님의 은혜를 계산한다 해도 너희는 그것을 헤아 릴 수 없으니 실로 하나님은 관용과 자비로 충만하심이라`]},"is-55-13":{e:`quranenc-korean-rwwad`,t:[`그럼에도 그대들(인간과 진)은 그대들 주님의 은총 중에서 그 무엇을 부정하려는 것인가?`]},"is-25-63":{e:`quranenc-korean-hamid`,t:[`자애로우신 하나님의 종들이 라 함은 대지위를 걸으매 겸허하 고 무지한 자들이 시비를 하매 평 화가 있으소서 라고 말하는 이들 이라`]},"is-31-18":{e:`quranenc-korean-hamid`,t:[`그리고 너의 얼굴을 돌려 사람들을 경멸하지 말것이며 걸음을 걸을 때면 거만하지 말라 실로 하 나님께서는 오만한 자들을 사랑하 시지 아니 하니라`]},"is-17-37":{e:`quranenc-korean-hamid`,t:[`오만함으로 대지를 걷지 말 라 너희가 그 대지를 가르지 못하며 산 높이에 이르지 못하니라`]},"is-23-1-2":{e:`quranenc-korean-hamid`,t:[`믿는 사람들은 번성하나니`,`이들은 예배에 임하여 겸손하는 자들이며`]},"is-57-23":{e:`quranenc-korean-rwwad`,t:[`그리하여 그대들이 놓친 것에 애통하지 아니하고 그분께서 그대들에게 주신 것에 희희낙락하지 않기 위해서라. 하나님께서는 뻐기고 잘난 체하는 그 어떤 자도 사랑하지 않으시노라.`]},"is-28-83":{e:`quranenc-korean-hamid`,t:[`하나님은 거만해 하지 아니 하고 지상에서 해악을 퍼뜨리지 아니한 이들에게 내세의 안식을 주리니 축복 받은 종말은 사악함 을 멀리하는 이들을 위해 있노라`]},"is-20-46":{e:`quranenc-korean-hamid`,t:[`이에 그분께서 두려워 하지 말라 내가 너희와 함께 있으며 듣고 그리고 보고 있노라`]},"is-41-30":{e:`quranenc-korean-rwwad`,t:[`실로 "우리의 주님은 하나님입니다"라고 말하고 그 후 (종교에 있어) 굳건했던 자들은 그들에게 천사들이 내려올 것이라. "그대들은 두려워하거나 슬퍼하지 말며, 그대들이 약속 받았던 천국의 소식으로 기뻐하라”`]},"is-46-13":{e:`quranenc-korean-rwwad`,t:[`실로 "우리의 주님은 하나님이십니다"라고 말한 후에 (종교에 있어) 굳건했던 자들은 그들에게 두려움이란 없을 것이며 실로 그들은 슬퍼하지도 않을 것이라.`]},"is-28-7":{e:`quranenc-korean-hamid`,t:[`하나님은 모세의 어미에게 계시하여 그에게 젖을 먹이도록 하 고 만일 그의 신변에 두려움을 느낄때는 그를 강물로 던지되 두려 워하지 말고 슬퍼하지도 말라 그 분은 그를 너에게로 돌려 줄 것이며 그를 선지자 가운데 하나로 만들 것이라`]},"is-10-62":{e:`quranenc-korean-rwwad`,t:[`보라. 실로 하나님의 동료, 그들에게 두려움이란 없을 것이며 실로 그들은 슬퍼하지도 않을 것이라.`]},"is-3-159":{e:`quranenc-korean-rwwad`,t:[`그리하여 하나님으로부터의 자비에 의해 그대(무함마드)는 그들을 친절히 대하였도다. 만약 그대가 가혹하고 마음이 모질었다면 실로 그들은 그대 주위로부터 떨어져 나갔을 것이라. 그러니 그대는 그들에게 관용을 베풀고 그들을 위해 용서를 빌어 주며 일의 결정에 있어 그들에게 의견을 구하라. 그리하여 결심이 섰다면 그대는 하나님께 의탁하라. 실로 하나님께서는 의탁하는 자를 사랑하시노라.`]},"is-24-22":{e:`quranenc-korean-hamid`,t:[`은혜와 복을 받는 자가 친척과 필요한 자와 하나님의 사업을 위해 집을 떠난 그들에게 자선을 베풀지 아니하려 맹세하는자 너희 가운데 없도록 하라 그리고 그들 로 하여금 관용을 베풀도록 하라 너희는 하나님께서 너희에게 관용 올 베풀어 줄 것을 원하지 아니하 느뇨 실로 하나님은 관용과 자비 로 충만 하심이라`]},"is-3-134":{e:`quranenc-korean-rwwad`,t:[`그들은 쉬울 때나 어려울 때나 베푸는 자들이며 분노를 참는 자들이며 사람들에게 관용을 베푸는 자들이라. 하나님께서는 최선을 다하는 자들을 사랑하시노라.`]},"is-42-43":{e:`quranenc-korean-rwwad`,t:[`실로 인내하고 용서하는 자가 있다면 참으로 그것은 단호한 의지가 요구되는 일이라.`]},"is-41-34":{e:`quranenc-korean-rwwad`,t:[`선행과 악행은 결코 같지 않노라. 그대는 더 훌륭한 것으로 (악행을) 물리치라. 그리하면 보라, 그대와의 관계에서 적의에 있던 자도 마치 절친한 동료처럼 될 것이라.`]},"is-7-199":{e:`quranenc-korean-rwwad`,t:[`그대는 관용을 취하고 선을 명하되 무지한 자들은 놓아두라.`]},"is-42-37":{e:`quranenc-korean-rwwad`,t:[`그들은 커다란 죄와 추악한 행위를 피하며, 화가 났을 때 실로 그들은 용서를 베푸노라.`]},"is-2-269":{e:`quranenc-korean-rwwad`,t:[`그분께서는 원하는 자에게 지혜를 주시니 지혜를 받은 자는 진실로 좋은 것을 풍족히 받은 것이라. 오직 슬기를 지닌 자들만이 깊이 생각하노라.`]},"is-20-114":{e:`quranenc-korean-hamid`,t:[`하나님은 모든 것 위에 계 시며 왕이요 진리이시니 그분의 말씀이 종료될 때까지 꾸란의 계 시를 서둘지 말고 주여 저에게 지식을 더하여 주옵소서`]},"is-39-9":{e:`quranenc-korean-rwwad`,t:[`밤 시간에 부복하고 기립하면서 (하나님께) 부단히 복종하고, 내세를 유의하며, 자신의 주님의 자비를 염원하는 자가 (저들과 같다는) 것인가? 그대(무함마드)는 말하라. "아는 자들과 알지 못하는 자들이 동일하단 말인가?" 오직 슬기를 지닌 자들만이 깊이 생각하노라.`]},"is-17-36":{e:`quranenc-korean-hamid`,t:[`너희가 알지 못하는 것을 따르지 말라 들었던 것과 보았던 것과 마음속에 있었던 모든 것에 관하여 심판의 날 질문을 받으리라`]},"is-96-1-5":{e:`quranenc-korean-rwwad`,t:[`창조하시는 그대(무함마드) 주님의 이름으로 읽어라.`,`그분께서는 매달린 것으로부터 인간을 창조하셨도다.`,`그대(무함마드)는 읽어라. 그대의 주님은 가장 풍성히 베푸시는 분이라.`,`그분께서는 (인간에게) 펜으로 (쓰는 법을) 가르쳐 주셨으니`,`인간이 알지 못했던 것을 가르쳐 주셨노라.`]},"is-58-11":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 앉은 자리에서 누군가가 그대들에게 “자리를 넓혀 주시오”라고 말하면 넓혀 주라, 하나님께서 그대들을 위해 넓혀 주실 것이라. 누군가가 “일어나 주시오”라고 말하면 그대들은 일어나 주라, 하나님께서 그대들 중에 믿는 자들과 지식을 받은 자들의 위치를 높여 주실 것이라. 하나님께서는 그대들이 행하는 일에 밝으신 분이라.`]},"is-2-261":{e:`quranenc-korean-rwwad`,t:[`하나님의 길에서 자신의 재산을 베푸는 자들의 예는 일곱 개의 이삭을 자라나게 한 낟알과도 같으니 이삭 하나마다 백 개의 낟알이 있도다. 하나님께서는 원하시는 자를 위해 (보상을) 불려 주시노라. 하나님께서는 (은혜가) 드넓으신 분이며 알고 계시는 분이라.`]},"is-3-92":{e:`quranenc-korean-rwwad`,t:[`그대들이 사랑하는 것으로써 베풀기 전까지는 그대들이 (진정한) 신앙을 얻지 못할 것이라. 그대들이 어떠한 것으로 베푼대도 실로 하나님께서는 그것을 알고 계시는 분이라.`]},"is-2-263":{e:`quranenc-korean-rwwad`,t:[`친절한 말과 용서는 해 끼침이 뒤따르는 자선보다 더 좋으니라. 하나님께서는 스스로 풍족하신 분이며 가장 관대히 용인하시는 분이라.`]},"is-76-8-9":{e:`quranenc-korean-rwwad`,t:[`불우한 자와 고아와 포로에게 자신이 애착하는 음식을 주더라.`,`‘우리가 그대들에게 음식을 줌은 오직 하나님의 얼굴을 위함이며 우리는 그대들로부터 보상이나 감사도 원하지 않노라.`]},"is-93-9-10":{e:`quranenc-korean-rwwad`,t:[`그러니 그대는 고아에 관하여는 윽박지르지 말고`,`구걸하는 자에 관하여는 질책하지 말며`]},"is-64-16":{e:`quranenc-korean-rwwad`,t:[`그러니 그대들은 능력껏 하나님을 두려워하고 듣고 따르며 그대들 자신을 위해 좋은 것으로써 베풀라. 마음의 각박함으로부터 벗어난 자, 이들이야말로 성공한 자들이라.`]},"is-7-31":{e:`quranenc-korean-rwwad`,t:[`아담의 자손들이여. (예배를 위해)성원에 있을 때면 항상 그대들의 미복(美服)을 취하라. 그리고 먹고 마시되 도를 지나치지 말라. 실로 그분께서는 도를 지나치는 자들을 사랑하지 않으시노라.`]},"is-25-67":{e:`quranenc-korean-hamid`,t:[`돈을 쓰되 낭비하지 아니하 고 인색하지 아니하며 항상 그 사 이의 중용을 택하는 자들이며`]},"is-17-29":{e:`quranenc-korean-hamid`,t:[`너희 손이 너희 목에 족쇄가되지 않도록 할 것이되 너무 펼 처도 아니 되나니 이는 너희가 비난을 받지 아니하고 빈곤하지 아 니하도록 함이라`]},"is-79-40-41":{e:`quranenc-korean-rwwad`,t:[`그러나 자신의 주님 앞에 서는 일을 두려워하며 자신의 욕구를 절제하던 자는`,`실로 천국, 그곳이 거주지가 될 것이라.`]},"is-31-19":{e:`quranenc-korean-hamid`,t:[`걸을 때는 겸손하고 너의 목소리를 낮추어라 가장 중오스러운 목소리는 당나귀 같은 소리라`]},"is-6-141":{e:`quranenc-korean-rwwad`,t:[`덩굴 올려진 또한 덩굴 올려지지 않은 정원과 야자수와 먹는 부위가 다른 농작물과 서로 비슷하면서도 비슷하지 않은 올리브와 석류를 만드신 분이 그분이시라. 그것이 열매를 낼 때 그대들은 그것으로부터 먹되 그것을 수확하는 날 그것에 부과된 의무를 다하라. 그리고 도를 지나치지 말라. 실로 그분께서는 도를 지나친 자들을 사랑하지 않으시노라.`]},"is-53-39-40":{e:`quranenc-korean-rwwad`,t:[`인간은 오직 노력한 것만을 가질 것이며`,`그의 노력은 곧 보여지게 될 것이며`]},"is-94-7-8":{e:`quranenc-korean-rwwad`,t:[`그러니 (일과를) 끝마쳤을 때 그대는 (경배 행위에) 매진하고`,`그대 주님께로 소망하라.`]},"is-62-10":{e:`quranenc-korean-rwwad`,t:[`그리하여 예배가 종료되었을 때 그대들은 대지로 흩어져 하나님의 은혜를 간구하라. 그리고 하나님을 많이 떠올리라, 그대들이 성공하게 될 것이라.`]},"is-67-15":{e:`quranenc-korean-rwwad`,t:[`그대들을 위해 대지가 순응토록 하신 분이 그분이시니 그대들은 그(대지) 끝자락을 걷고 그분의 양식을 먹으라. 그리고 그분께로 부활이 있을 것이라.`]},"is-18-30":{e:`quranenc-korean-hamid`,t:[`그러나 믿음으로 선을 행한 그에게는 실로 하나님은 보상이 헛되지 않게 하리라`]},"is-2-153":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 인내심과 예배로써 (하나님께) 도움을 요청하라. 실로 하나님께서는 인내하는 자들과 함께 하시노라.`]},"is-103-1-3":{e:`quranenc-korean-rwwad`,t:[`시간을 두고 맹세코`,`진실로 인간은 손실 속에 있노라.`,`그러나 (하나님과 사도를) 믿고 선행을 실천하며 서로에게 진리를 권유하고 서로에게 인내를 권유하는 자들은 예외라.`]},"is-39-10":{e:`quranenc-korean-rwwad`,t:[`그대(무함마드)는 말하라. "(하나님을) 믿는 나의 종복들이여, 그대들의 주님을 경외하라. 이 현세에서 최선을 다하는 자에게는 좋은 것이 있을 것이라. 하나님의 대지는 넓도다. 진정코 인내하는 자들은 자신의 풍성한 보상을 따짐 없이 받을 것이라"`]},"is-70-5":{e:`quranenc-korean-rwwad`,t:[`그러니 그대는 아름답게 인내하라.`]},"is-2-155-156":{e:`quranenc-korean-rwwad`,t:[`진실로 나는 두려움과 배고픔, 재산과 생명과 열매의 감소 같은 것으로써 그대들을 시험할 것이라. 그리고 그대는 인내하는 자들에게 기쁜 소식을 전하라.`,`그들에게 시련이 닥쳤을 때 그들은 말하더라. “실로 우리는 하나님의 소유이며 실로 우리는 그분께로 돌아가게 될 것입니다”`]},"is-11-115":{e:`quranenc-korean-rwwad`,t:[`그대는 인내할지니, 실로 하나님께서는 최선을 다하는 자들의 보상을 저버리지 않으시기 때문이라.`]},"is-13-28":{e:`quranenc-korean-rwwad`,t:[`그들은 믿고, 하나님을 떠올림으로써 그들의 마음이 평온해지는 자들이라. 보라, 마음은 하나님을 떠올림으로써 비로소 평온해지노라.`]},"is-10-25":{e:`quranenc-korean-rwwad`,t:[`하나님께서는 (사람들을) 평안의 거주지로 초대하시며 원하시는 자를 올곧은 길로 인도하시노라.`]},"is-49-10":{e:`quranenc-korean-rwwad`,t:[`믿는 자들은 다름 아닌 형제들이니 그대들은 그대들의 두 형제 사이를 중재하라. 그리고 하나님을 경외하라, 그대들이 자비를 받게 될 것이라.`]},"is-6-54":{e:`quranenc-korean-rwwad`,t:[`나의 징표를 믿는 자들이 그대(무함마드)를 찾아왔을 때는 "그대들에게 평안이 깃들기를" 이라고 말하라. 그대들의 주님께서는 당신 자신께 자비를 의무화 하셨노라: 실로, 그대들 중에 무지로 말미암아 악행을 저지른 자가 그 이후에 뉘우치고 행실을 개선한다면 실로 그분께서는 너그러이 용서하시는 자애로우신 분이라.`]},"is-36-58":{e:`quranenc-korean-rwwad`,t:[`(그들에게는) "평안하라"는 자애로우신 주님의 말씀이 있노라.`]},"is-7-56":{e:`quranenc-korean-rwwad`,t:[`대지가 바로잡힌 후에 그곳에서 해악을 퍼뜨리지 말며, 두려움과 희망으로 그분께 기도하라. 실로 하나님의 자비는 최선을 다하는 자들에게 가까이 있노라.`]},"is-94-5-6":{e:`quranenc-korean-rwwad`,t:[`그러니 실로 어려움과 함께 쉬움이 있노라.`,`실로 어려움과 함께 쉬움이 있노라.`]},"is-93-3-5":{e:`quranenc-korean-rwwad`,t:[`그대의 주님께서는 그대를 버려 두지도 혐오하지도 않으시노라.`,`실로 그대에겐 내세가 현세보다 더 좋으며`,`정녕코 그대의 주님께서 그대에게 베푸실 것이니 그대는 만족할 것이라.`]},"is-65-7":{e:`quranenc-korean-rwwad`,t:[`풍족한 자는 그의 풍족함으로 부양하고, 양식이 한정된 자는 하나님께서 그에게 주신 것으로 부양토록 하라. 하나님께서는 영혼에게 오직 주신 만큼만 짐 지우시노라. 하나님께서는 어려움 후에 평이함을 두실 것이라.`]},"is-2-186":{e:`quranenc-korean-rwwad`,t:[`나의 종복들이 그대(무함마드)에게 나에 관해 묻거든 실로 나는 가까이 있노라. 기도하는 자가 나에게 요청할 때 나는 그의 기도에 응답하노라. 그러니 그들이 나의 부름에 응하도록 하고 나를 믿도록 하라. 그들이 올바른 길로 인도될 것이라.`]},"is-50-16":{e:`quranenc-korean-rwwad`,t:[`진실로 내가 인간을 창조하였으니 나는 그의 마음이 그에게 속삭이는 것이 무엇인지를 알고 있노라. 그리고 나는 목정맥의 혈관보다 그에게 (지식으로써) 더 가까이 있노라.`]},"is-12-86":{e:`quranenc-korean-rwwad`,t:[`그가 말하였노라. "나는 그저 하나님께 나의 참담함과 슬픔을 호소하는 것뿐이라. 그리고 나는 하나님을 통해 너희가 알지 못하는 것을 알고 있노라"`]},"is-39-53":{e:`quranenc-korean-rwwad`,t:[`그대(무함마드)는 말하라. “자기 자신에게 도를 지나쳤던 나의 종복들이여! 하나님의 자비를 체념하지 말라. 실로 하나님께서는 그 모든 죄를 용서해 주시노라. 진실로 그분께서는 너그러이 용서하시는 분이며 가장 자애로우신 분이라”`]},"is-65-3":{e:`quranenc-korean-rwwad`,t:[`그리고 그분께서는 그가 예상치 못한 곳에서 그에게 양식을 베푸실 것이라. 하나님께 의탁하는 자, 그는 그분만으로 충분하도다. 실로 하나님께서는 그분의 일을 이루시는 분이라. 실로 하나님께서는 모든 것에 알맞은 양을 두셨도다.`]},"is-18-46":{e:`quranenc-korean-hamid`,t:[`재물과 자손은 현세의 장식 에 불과하나 선행으로 주님으로 부터 가장 좋은 보상과 가장 좋은소망을 가질 것이라`]},"is-4-110":{e:`quranenc-korean-rwwad`,t:[`악행을 저지르거나 자신을 부당히 다룬 자가 그 후에 하나님께 용서를 구한다면 그는, 하나님께서 너그러이 용서하시는 자애로우신 분임을 발견할 것이라.`]},"is-2-214":{e:`quranenc-korean-rwwad`,t:[`그대들에게 그대들 이전에 이미 지나갔던 자들(이 겪은 시련)의 예가 오지 않았는대도 그대들은 천국에 들어가리라 생각했던 것인가? 빈곤과 어려움이 그들을 덮쳤고 그들은 동요하였으니 사도와 그와 함께 믿는 자들은 끝내 “하나님의 도움은 언제입니까?”라고 말하더라. 실로 하나님의 도움은 가깝지 아니하던가!`]},"is-42-28":{e:`quranenc-korean-rwwad`,t:[`그들이 체념한 후에 해갈의 비를 내리시고 당신의 자비를 퍼뜨리시는 분이 그분이시라. 그분께서는 가호자이시며 가장 영광되신 분이라.`]},"is-2-172":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 그대들이 하나님만을 경배하는 자들이라면 내가 그대들에게 베푼 좋은 양식을 먹고 그분께 감사하라.`]},"is-16-114":{e:`quranenc-korean-hamid`,t:[`그러므로 하나님께서 너희 에게 베푼 허락된 좋은 것으로 일 용할 양식을 하되 하나님의 은혜 에 감사하고 그분만을 경배하라`]},"is-46-15":{e:`quranenc-korean-rwwad`,t:[`나는 인간에게 명령하길 부모님께 효도하라 하였노라. 그의 어머니는 그를 힘겹게 배고 다니며, 힘겹게 출산하노라. 그의 임신과 젖 떼기는 삼 십 개월이라. 그리하여 그가 왕성한 기력에 이르고 마흔에 이르렀을 때 그가 말하였노라. "주님. 저에게 영감을 불어넣으시어, 제가 당신께서 저와 부모님에게 베풀어 주신 은총에 감사하고, 당신께서 흡족해 하실 선행을 실천할 수 있도록 해 주십시오. 그리고 저를 위해 제 후손들 사이에 선량함을 내려 주십시오. 실로 저는 당신께 참회하였고, 실로 저는 순종하는 자들(무슬림들) 중의 하나입니다.`]},"is-16-78":{e:`quranenc-korean-hamid`,t:[`하나님께서 너희를 어머니 태내에서 나오게 하사 너희는 조 금도 알지 못함이라 그리고 그분 은 너희에게 청각과 시각과 지혜 를 주셨으니 감사하라`]},"is-49-13":{e:`quranenc-korean-rwwad`,t:[`사람들이여! 실로 나는 한 명의 남자와 한 명의 여자를 통해 그대들을 창조하였고, 서로를 알 수 있도록 그대들을 민족과 부족으로 두었노라. 실로 하나님 보시기에 가장 명예로운 자는 그대들 중에 가장 높은 경외심을 지닌 자라. 실로 하나님께서는 알고 계시며 일에 밝으신 분이라.`]},"is-7-55":{e:`quranenc-korean-rwwad`,t:[`그대들의 주님께 간절하고 내밀하게 기도하라. 실로 그분께서는 경계를 넘어서는 자들을 사랑하지 않으시노라.`]},"is-53-32":{e:`quranenc-korean-rwwad`,t:[`그들은 커다란 죄와 추악한 행위를 피하는 자들이나 스쳐 지나가는 것은 예외라. 실로 그대의 주님은 용서하심에 드넓은 분이시라. 그분께서는 누구보다 그대들을 더 잘 알고 계신 분이니, 그분께서는 흙으로부터 그대들을 만드셨고 그대들은 그대들의 어머니 뱃속에 있는 태아였노라. 그러니 그대들은 자신이 깨끗하다 생각하지 말라. 그분께서는 누가 (하나님을) 두려워하는지 가장 잘 알고 계신 분이라.`]},"is-17-23":{e:`quranenc-korean-hamid`,t:[`주님이 명령하사 그분 외에는 경배하지 말라 했으며 부모에 게 효도하라 하셨으니 그들중 한 사람 또는 두 사람이 나이들 때 그들을 멸시하거나 저항치말고 고운말을 쓰라 하셨노라`]},"is-20-68":{e:`quranenc-korean-hamid`,t:[`하나님이 말하길 두려워 하 지 말라 실로 네가 위에 있노라`]},"is-33-3":{e:`quranenc-korean-hamid`,t:[`하나님께 의탁하라 하나님만 이 보호자로써 충분하니라`]},"is-29-69":{e:`quranenc-korean-hamid`,t:[`그러나 안에서 노력하는 자하나님은 그들을 그분의 길로 인 도하리니 하나님은 의로움으로 행하는 그들과 함께 하시니라`]},"is-26-62":{e:`quranenc-korean-hamid`,t:[`결코 그렇지 아니하거늘 나 의 주님께서는 나와 같이 하시어 나를 인도하시니라`]},"is-4-149":{e:`quranenc-korean-rwwad`,t:[`만약 그대들이 좋은 것을 드러내거나 그것을 숨기거나 악행에 대해 관용을 베푼다면 실로 하나님께서는 관용을 베푸시고 능력을 가지신 분이도다.`]},"is-23-96":{e:`quranenc-korean-hamid`,t:[`선행으로 악을 쫓으라 하나 님은 그들이 말하는 것을 알고 있노라`]},"is-28-55":{e:`quranenc-korean-hamid`,t:[`그들이 공허한 말을 들을 때에는 등을 돌리며 우리에게는 우리의 일이 있고 너희에게는 너 희의 할 일이 있나니 당신들께 평화가 있기를 바랍니다 우리는 무 지한 자들을 원치 않습니다 라고 말하더라`]},"is-60-7":{e:`quranenc-korean-rwwad`,t:[`하나님께서 그대들과, 그들 중에 그대들이 적의를 보였던 자들 사이에 사랑을 불어넣으실지도 모르는 일이라. 하나님께서는 능력을 가지신 분이라. 그리고 하나님께서는 너그러이 용서하시는 자애로우신 분이라.`]},"is-3-190":{e:`quranenc-korean-rwwad`,t:[`진실로 하늘과 땅의 창조와 밤과 낮의 교체에는 슬기를 지닌 자들을 위한 징표들이 있노라.`]},"is-49-6":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 일탈을 일삼는 자가 그대들에게 어떤 소식을 가지고 왔다면 확실히 확인하라. 이는, 그대들이 사람들을 무지로써 해를 끼친 후 그대들이 저지른 일에 대해 후회하는 자가 되지 않기 위해서라.`]},"is-16-125":{e:`quranenc-korean-hamid`,t:[`지혜와 아름다운 설교로 모두를 하나님의 길로 인도하되 가 장 훌륭한 방법으로 그들을 맞으 라 하나님은 그분의 길을 벗어난 자와 바른 길로 가는자를 알고 계 심이라`]},"is-39-18":{e:`quranenc-korean-rwwad`,t:[`그들은 말씀을 경청하며 그 중에서도 가장 훌륭한 것을 따르는 자들이라. 저들은 하나님께서 인도해 주신 자들이며, 저들이야말로 슬기를 지닌 자들이라.`]},"is-2-274":{e:`quranenc-korean-rwwad`,t:[`비밀리에 그리고 공개리에 자신의 재산을 밤낮으로 베푸는 자들, 그들에게는 그들 주님으로부터 그들의 보상이 있을 것이며 그들에게 두려움이란 없을 것이며 그들은 슬퍼하지도 않을 것이라.`]},"is-2-215":{e:`quranenc-korean-rwwad`,t:[`그들이 그대에게 무엇으로 베풀어야 하는지 물으니, 말하라. “그대들이 쓰는 재산이라. 그리고 (그것은) 부모님과 가까운 친척과 고아와 불우한 자와 장거리 이동 중인 자를 위한 것이라” 그대들이 선행을 행한다면 실로 하나님께서는 그것을 알고 계시는 분이라.`]},"is-57-7":{e:`quranenc-korean-rwwad`,t:[`그대들은 하나님과 그분의 사도를 믿고 그분께서 그대들을 계승인으로 두신 것으로써 베풀라. 그대들 중에 (하나님을) 믿고 베푼 자, 그들에게는 커다란 보상이 있을 것이라.`]},"is-59-9":{e:`quranenc-korean-rwwad`,t:[`그리고 (공물 전리품은) 그들(메카 이주민) 이전에 (메디나) 거주지에 거처하고 믿은 자들(메디나 정착민)의 것으로, 그들(메디나 정착민)은 그들에게로 이주해 온 자들을 사랑하고 그들(메카 이주민)이 받은 것에 대하여 자신들의 가슴 속에서 욕심을 발견하지 못하더라. 그리고 그들은 자신들에게 절실한 필요가 있음에도 자기 자신들을 두고 (그들에게) 양보하더라. 마음의 각박함으로부터 벗어난 자, 이들이야말로 성공한 자들이라.`]},"is-2-183":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 그대들 이전의 자들에게 의무 사항으로 규정되었던 것처럼 그대들에게도 단식이 의무 사항으로 규정되었으니 그대들이 (하나님을) 경외하게 될 것이라.`]},"is-28-77":{e:`quranenc-korean-hamid`,t:[`하나님께서 너에게 베풀어 준 것으로 내세의 안식처를 구하 라 그리고 현세에서 너의 몫을 망각하지 말며 하나님께서 너에게 선을 베푸셨던 것처럼 선을 베풀 되 땅 위에 해악을 퍼뜨리지 말라실로 하나님은 해악을 퍼뜨리는 자를 사랑하지 아니 하시니라`]},"is-20-131":{e:`quranenc-korean-hamid`,t:[`하나님이 그들중 일부에게 준 현세의 영화에 눈을 돌리지 말 라 실로 하나님은 그것을 통하여 그들을 시험하노라 주님이 주시는 양식은 가장 좋은 것이요 영원한 것이라`]},"is-17-26":{e:`quranenc-korean-hamid`,t:[`친척과 불쌍한 사람과 여행 자에게도 자선을 베풀되 낭비하지말라`]},"is-2-45":{e:`quranenc-korean-rwwad`,t:[`그대들(믿는 자들)은 인내와 예배로써 (하나님께) 도움을 요청하라. 진실로 그것(예배)은 어려운 것이나 (하나님께) 자신을 낮추는 자들에게는 예외라.`]},"is-13-22":{e:`quranenc-korean-rwwad`,t:[`그들 주님의 얼굴을 간구하면서 인내하고, 성실히 예배를 드리며, 내가 그들에게 제공한 것으로써 비밀리에 그리고 공개리에 베풀며, 선으로 악을 물리치는 자들, 실로 그들에게는 궁극의 안식처가 있을 것이라.`]},"is-31-17":{e:`quranenc-korean-hamid`,t:[`나의 아들아 예배를 드리라 그리고 선을 행하고 악을 금하며 네가 당하는 모든 것에 인내하라 이것은 실로 용기가 필요한 것이 니라`]},"is-52-48":{e:`quranenc-korean-rwwad`,t:[`그러니 그대(무함마드)는 그대 주님의 판결에 인내하라, 실로 그대는 나의 배려와 함께 하노라. 그대가 일어날 때는 그대 주님의 완벽한 영광을 드높이라.`]},"is-10-57":{e:`quranenc-korean-rwwad`,t:[`사람들이여! 그대들에게 그대들 주님으로부터의 가르침과, 가슴 속에 있는 것에 대한 치유와, 인도와, 믿는 자들을 위한 자비가 도래하였노라.`]},"is-16-97":{e:`quranenc-korean-hamid`,t:[`믿음으로 선을 행하는 모든 남녀에게 하나님은 행복한 삶을 부여할 것이며 또한 하나님은 그 들이 행한 선에 대하여 최상의 것으로 보상 하리라`]},"is-33-41-42":{e:`quranenc-korean-hamid`,t:[`믿음을 가진 자들아 하나님 을 많이 염원하라`,`그리고 그분을 조석으로 찬 미하라`]},"is-20-25-28":{e:`quranenc-korean-hamid`,t:[`이때 모세가 주여 저를 위해저의 마음을 활짝 열어주소서`,`그리고 저의 일이 쉽도록 하여 주소서`,`저의 혀에 장애물을 제거하 여 주조서`,`그리하여 그들이 저의 말을 이해하도록 하여 주소서`]},"is-93-6-8":{e:`quranenc-korean-rwwad`,t:[`그분께서 그대가 고아임을 발견하고 감싸 주지 않으셨던가?`,`그리고 그분께서는 그대가 방황하는 자임을 발견하고 인도해 주셨고`,`그대가 궁함을 발견하고 충족시켜 주셨노라.`]},"is-21-87-88":{e:`quranenc-korean-hamid`,t:[`요나에 관한 이야기를 그대 의 백성에게 상기하리니 그는 화 가나 떠나며 하나님이 그를 제압 하지 못하리라 추측했노라 그러나 그도 역경에 처할 때는 실로 당신 외에는 신이 없나니 당신만을 찬 미하나이다 저는 실로 죄인들 무 리중에 있었습니다 하더라`,`하나님은 호소에 응하사 그 를 고통으로부터 구하고 믿는 신 앙인들을 구원했노라`]},"is-23-62":{e:`quranenc-korean-hamid`,t:[`하나님은 능력 이상으로 무 거운 짐을 주지 아니하며 진리를 보여주는 기록을 가지고 있으니 그들은 결코 불공평한 대접을 받 지 않노라`]},"is-94-1-4":{e:`quranenc-korean-rwwad`,t:[`내가 그대의 가슴을 열어 넓히지 않았던가?`,`나는 그대의 짐을 내려 주었으니`,`그대의 등골을 분지르던 짐이라.`,`그리고 나는 그대를 위하여 그대의 명예를 높여 주었노라.`]},"is-3-133":{e:`quranenc-korean-rwwad`,t:[`그대들은 그대들 주님으로부터의 용서와 천국을 위해 서두르라. 그 너비는 하늘과 땅의 너비이며 하나님을 경외하는 자들을 위해 준비되었노라.`]},"is-15-56":{e:`quranenc-korean-hamid`,t:[`아브라함이 대답하더라 방황하는자 외에는 누가 주님의 은혜 를 실망시키리요`]},"is-25-70":{e:`quranenc-korean-hamid`,t:[`그러나 회개하여 믿음을 갖 고 선을 행하는 자들에게는 실로 하나님께서 그들의 잘못을 선으로받아 주시거늘 하나님은 관용과 자비로 충만하심이라`]},"is-42-19":{e:`quranenc-korean-rwwad`,t:[`하나님께서는 당신의 종복들에게 자상하신 분이며 원하시는 자에게 양식을 베푸시노라. 그리고 그분께서는 가장 강하시고 가장 존엄하신 분이라.`]},"is-61-2-3":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 왜 그대들은 행하지 않는 일을 말하는가?`,`그대들이 행하지 않는 일을 말함은 하나님께 있어 매우 혐오스러운 것이라.`]},"is-17-35":{e:`quranenc-korean-hamid`,t:[`물건을 재되 되를 가득 채을것이요 무게를 달되 저울의 균형 을 이루게 하라 이것이 선이요 내세에서 가장 좋은 재산이라`]},"is-23-8":{e:`quranenc-korean-hamid`,t:[`그들의 신용을 지키고 계약을 준수하는 자들이며`]},"is-99-7-8":{e:`quranenc-korean-rwwad`,t:[`티끌만큼의 무게라도 선행을 실천한 자는 그것을 보게 될 것이며`,`티끌만큼의 무게라도 악행을 저지른 자는 그것을 보게 될 것이라.`]},"is-49-11":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 한 무리가 다른 무리를 깔보지 않도록 하라: 그들이 (다른) 그들보다 더 훌륭할 지도 모를 일이라. 여성들이 다른 여성들에 대해서도 그렇게 하지 말라: 그녀들이 (다른) 여성들보다 더 훌륭할 지도 모를 일이라. 그리고 그대들 자신을 비웃지 말며 서로를 나쁜 별명들로 부르지도 말라. 믿음 이후의 일탈이란 얼마나 사악한 이름인가. 뉘우치지 않는 자, 저들은 실로 부당한 자들이라.`]},"is-31-14":{e:`quranenc-korean-hamid`,t:[`하나님은 모든 인간에게 명령하여 부모를 존경하라 했거늘 그의 어머니는 태아를 가짐과 이 년간 젖을 먹이므로 말미암아 허 약하여지니라 내게 감사하고 그리고 네 부모에게 감사하라 내게로 옴이 최후이니라`]},"is-16-53":{e:`quranenc-korean-hamid`,t:[`너희에게 베풀어지는 모든 은혜는 하나님으로부터 오는 것으로 너희에게 고난이 있을 때 그분에게만 구원하라`]},"is-45-12":{e:`quranenc-korean-rwwad`,t:[`그대들을 위해 바다를 유용케 하신 분이 하나님이시라. 그리하여 선박이 그분의 명령에 따라 그곳에서 항해하고 그대들이 그분의 은혜의 일부를 추구하니, 그대들이 감사하게 될 것이라.`]},"is-36-35":{e:`quranenc-korean-rwwad`,t:[`그들이 그 열매를 먹도록 함이니 그것(열매)은 그들의 손이 노역한 것이 아니라. 그러니 그들은 감사하지 않겠는가?`]},"is-30-46":{e:`quranenc-korean-hamid`,t:[`하나님의 예중 가운데 하나 는 바람을 보내어 기쁜 소식을 알리는 것과 너희로 하여금 그분 의 은혜를 맛보게 하는 것과 배 들이 그분의 명령에 따라 항해하 는 것과 너희가 그분의 풍성한 은혜를 구하는 것과 너희가 이에 감사하는 것이라`]},"is-7-10":{e:`quranenc-korean-rwwad`,t:[`진실로 나는 그대들에게 지상에서 능력을 주었고, 그대들을 위해 그곳에 양식을 두었노라. 그대들의 감사함이 참으로 적도다.`]},"is-40-61":{e:`quranenc-korean-rwwad`,t:[`그대들을 위해 밤을 두시어 그대들이 그 안에서 편안함을 찾고, 낮을 두시어 시각의 제공자로 하신 분이 하나님이시라. 진실로 하나님께서는 인간에게 내려지는 은혜의 소유자이시나 대부분의 인간은 감사하지 않더라.`]},"is-25-62":{e:`quranenc-korean-hamid`,t:[`밤과 낮을 교대하게 하시는 분도 그분이시니 이는 하나님을 염원하고 감사하는 사람들을 위해 서라`]},"is-23-60":{e:`quranenc-korean-hamid`,t:[`주님께로 돌아갈 것을 두려 워하며 마음으로 자선을 베푼자 있나니`]},"is-32-15":{e:`quranenc-korean-hamid`,t:[`말씀이 낭송될 때 하나님의말씀을 믿는 자들은 부복하고 주 님의 영광을 찬미하며 거만하지 아니하노라`]},"is-7-205":{e:`quranenc-korean-rwwad`,t:[`속으로 간절하고 내밀하게, 말로 드러냄 없이 오전과 오후에 그대 주님을 떠올리라. 그리고 그대는 방심하는 자들 중의 하나가 되지 말라.`]},"is-22-35":{e:`quranenc-korean-hamid`,t:[`이들은 하나님을 염원할 때 마음에 두려움을 갖는 자들이며 어려움에 인내하는 자들이며 예배 를 행하는 자들이며 하나님이 그 들에게 준 양식으로 베푸는 자들 이라`]},"is-17-109":{e:`quranenc-korean-hamid`,t:[`그리고 그들은 엎드려 흐느끼니 그들의 겸손함이 더하여 지 더라`]},"is-3-17":{e:`quranenc-korean-rwwad`,t:[`(그들은) 인내하는 자들이며 진실된 자들이며 부단히 복종하는 자들이자 희사금을 내는 자들이며 새벽녘에 (하나님께) 용서를 구하는 자들이라.`]},"is-11-23":{e:`quranenc-korean-rwwad`,t:[`실로 (하나님과 사도를) 믿고 선행을 실천하며 자신의 주님께 겸허한 자들, 저들은 천국의 거주자들이니 실로 그들은 그 안에서 머물 것이라.`]},"is-25-64":{e:`quranenc-korean-hamid`,t:[`그들은 주님 앞에서 부복하고일어서 밤을 지새우는 자들이며`]},"is-2-112":{e:`quranenc-korean-rwwad`,t:[`그렇지 않노라. 최선을 다하는 자로서 자신의 얼굴을 하나님께 순종시키는 자가 있다면 그에게는 그의 주님으로부터의 보상이 있을 것이라. 그들에게 두려움이란 없을 것이며 그들은 슬퍼하지도 않을 것이라.`]},"is-6-48":{e:`quranenc-korean-rwwad`,t:[`​내가 사도를 보낼 때는 항상, 기쁜 소식의 전달자이자 경고자로서 그들을 보내노라. 그리하여 믿음을 가지고 행실을 개선하는 자가 있다면 그들에게 두려움이란 없을 것이며 그들은 슬퍼하지도 않을 것이라.`]},"is-7-35":{e:`quranenc-korean-rwwad`,t:[`아담의 자손들이여. 실로 그대들로부터 나온 사도들이 그대들에게 이르러 그들이 그대들에게 나의 징표를 이야기할 때, 만약 (하나님을) 경외하고 행실을 개선한 자가 있다면 그들에게 두려움이란 없을 것이며 그들은 슬퍼하지도 않을 것이라.​`]},"is-11-112":{e:`quranenc-korean-rwwad`,t:[`그러니, 그대는 명령받은 것처럼 (종교에 있어) 굳건하라. 그대와 함께 참회하는 자들도 마찬가지라. 그리고 그대들은 경계를 넘어서지 말라. 실로 그분께서는 그대들이 행하는 것을 보고 계시는 분이라.`]},"is-40-44":{e:`quranenc-korean-rwwad`,t:[`그러니 그대들은 내가 그대들에게 한 말을 곧 기억할 것입니다. 저는 저의 일을 하나님께 맡깁니다. 실로 하나님께서는 종복들을 보고 계시는 분이십니다`]},"is-16-128":{e:`quranenc-korean-hamid`,t:[`실로 하나님은 악을 멀리하는 이들과 선을 실천하는 이들과함께하시니라`]},"is-8-2":{e:`quranenc-korean-rwwad`,t:[`진정코 믿는 자들이란 하나님이 언급될 때면 그들의 마음이 전율하고, 그들에게 그분의 징표가 낭송될 때면 그들의 믿음이 증가하며, 오직 그들의 주님께만 의탁하는 자들이라.`]},"is-28-24":{e:`quranenc-korean-hamid`,t:[`그래서 그는 두 여인을 위하 여 양에게 물을 먹여주고 나무그 늘 아래 앉아 말했더라 주여 당 신께서 저에게 베풀어 주셨던 은 혜가 절실히 필요하나이다`]},"is-42-40":{e:`quranenc-korean-rwwad`,t:[`악에 대한 징벌은 그와 유사한 악이라. 그러나 관용을 베풀고 타협을 이루는 자, 그의 보상은 하나님의 몫이라. 실로 그분께서는 부당한 자들을 사랑하시지 않노라.`]},"is-25-72":{e:`quranenc-korean-hamid`,t:[`거짓 증언을 하지 아니하고 좋지 않은 곳을 지나갈 때 회피 하여 바르게 스쳐가는 자이며`]},"is-3-135":{e:`quranenc-korean-rwwad`,t:[`추악한 행위를 저지르거나 자신을 부당히 다루었을 때 그들은 하나님을 떠올리고선 자신의 죄에 대해 용서를 구하니, 하나님 이외에 죄를 용서해줄 자가 누구인가? 그들은 (그것이 죄임을) 알았을 때 그들이 했던 일을 계속하지 않노라.`]},"is-11-114":{e:`quranenc-korean-rwwad`,t:[`그대는 낮의 양 끝자락에 그리고 밤의 어귀에 성실히 예배를 드리라. 실로 선행은 악행을 없애주노라. 이는 기억하는 자들을 위한 떠올림이라.`]},"is-66-8":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님께 진실로 뉘우치라, 그대들 주님께서 그대들을 위해 그대들의 악행을 용서해 주시고 그대들을 아래로부터 강이 흐르는 천국에 들게 하실 것이라. 그날 하나님께서는 선지자와 그와 함께 믿었던 자들에게 (불지옥의) 치욕을 주지 않으실 것이라. 그들의 앞쪽과 오른쪽에는 그들의 빛이 펼쳐질 것이라. 그들이 말할 것이니: “저희의 주님! 저희를 위하여 저희의 빛을 완전히 하여 주시고 저희를 용서하여 주십시오. 실로 당신께서는 모든 것이 가능한 분이십니다”`]},"is-20-82":{e:`quranenc-korean-hamid`,t:[`실로 내가 관용을 베풀거늘 회개하고 믿음으로 선을 행하는 그에게 관용을 베푸니 그는 바른 길로 인도 받으리라`]},"is-4-17":{e:`quranenc-korean-rwwad`,t:[`하나님께서 뉘우침을 받아주심은 무지로 인해 사악함을 저지른 후 가까운 시일 내에 뉘우치는 자들에게 있으니, 이들은 하나님께서 그들의 뉘우침을 받아주실 것이라. 하나님께서는 아시는 분이며 지혜로우신 분이도다.`]},"is-41-31":{e:`quranenc-korean-rwwad`,t:[`“우리는 현세에서 그리고 내세에서 그대들의 조력자라. 그대들은 그곳(천국)에서 그대들 자아가 소망하는 것을 가질 것이며, 그대들은 그곳(천국)에서 그대들이 바라는 것을 가질 것이니”`]},"is-30-22":{e:`quranenc-korean-hamid`,t:[`천지를 창조하시고 너희의 언어들과 피부색을 달리 창조 하 셨음도 그분 예증의 하나이시니 실로 그 안에는 전 인류를 위한 예증이 있노라`]},"is-35-28":{e:`quranenc-korean-hamid`,t:[`사람도 동물도 가축도 그와 마찬가지로 여러가지 색깔을 두셨노라 그분의 종 가운데서 하나님 을 두려워 하는 자들은 지식을 가진 자들 뿐이나 실로 하나님은 권능과 관용으로 충만하심이라`]},"is-29-43":{e:`quranenc-korean-hamid`,t:[`하나님이 비유를 드사 이것 은 온 백성을 위해서라 지혜 있는자들은 이해하리라`]},"is-18-66":{e:`quranenc-korean-hamid`,t:[`그리하여 모세가 그에게 이 르길 당신의 지식을 배우기 위하 여 제가 당신을 따라 가도 되겠 습니까 라고 하니`]},"is-17-85":{e:`quranenc-korean-hamid`,t:[`그들이 성령에 관하여 그대 에게 물으리라 일러가로되 성령은주님 외에는 알지 못하는 것이며 너희가 아는 것은 미량에 불과하 니라`]},"is-88-17-20":{e:`quranenc-korean-rwwad`,t:[`그러니 그들은 낙타가 어떻게 창조되었는지 보지 않겠는가?`,`하늘이 어떻게 올려졌는지,`,`산은 어떻게 세워졌는지,`,`땅은 어떻게 평평하게 되었는지 그들은 보지 않겠는가?`]},"is-3-191":{e:`quranenc-korean-rwwad`,t:[`그들은 서서, 앉아서, 누워서 하나님을 떠올리고 하늘과 땅의 창조에 관하여 숙고하는 자들이라. “저희의 주님! 당신께서는 아무 목적 없이 이것을 창조하신 것이 아닙니다. 완벽하신 당신이십니다! 그러니 불지옥의 벌으로부터 저희를 구해 주십시오”`]},"is-2-164":{e:`quranenc-korean-rwwad`,t:[`진실로 하늘과 땅의 창조와, 밤과 낮의 교체, 인간에게 득이 되는 것을 싣고 바다를 항해하는 선박, 하나님께서 하늘에서 비를 내리시어 그것으로써 죽어 있던 대지에 생명을 불어넣으시고 그곳에 모든 종류의 기어 다니는 동물을 퍼뜨리심과, 바람의 변화무쌍함, 하늘과 땅 사이에 있는 굴종하는 구름에는 이성을 가진 사람들을 위한 징표가 있노라.`]},"is-2-262":{e:`quranenc-korean-rwwad`,t:[`실로 하나님의 길에서 자신의 재산을 베풀고 그 후 은근한 자랑이나 해 끼침이 그들이 베푼 것을 뒤따르도록 하지 않는 자들, 그들에게는 그들 주님으로부터 그들의 보상이 있노라. 그리고 그들에게 두려움이란 없을 것이며 그들은 슬퍼하지도 않을 것이라.`]},"is-2-245":{e:`quranenc-korean-rwwad`,t:[`하나님을 위해 돌려받지 않을 빚을 내주는 자가 누구인가? 그분께서는 그를 위해 그것을 여러 곱절로 불려 주실 것이니 하나님께서는 (양식을) 움키시고 펼치시노라. 그리고 그대들은 그분께로 돌아가게 될 것이라.`]},"is-2-271":{e:`quranenc-korean-rwwad`,t:[`만약 그대들이 자선을 드러낸다면 그것으로도 참으로 훌륭하노라. 그러나 만약 그대들이 그것을 숨기고 가난한 자들에게 준다면 그것은 그대들에게 더욱 훌륭한 것이라. 그분께서 그대들을 위해 그대들의 악행을 용서해 주실 것이라. 하나님께서는 그대들이 행하는 일에 밝으신 분이라.`]},"is-2-273":{e:`quranenc-korean-rwwad`,t:[`(희사는) 가난한 자들을 위한 것이니 그들은 하나님의 길에서 제약을 받아 대지를 떠날 수 없노라. 무지한 자는 절제함으로 인해 그들을 부유한 자들로 생각하더라. 그대는 그들의 표징으로써 그들을 알며, 그들은 여기저기 사람들에게 구걸하지 않노라. 그대들이 재산으로 베푼다면 실로 하나님께서는 그것을 알고 계시는 분이라.`]},"is-30-38":{e:`quranenc-korean-hamid`,t:[`그러므로 친척과 필요로 하 는 자와 여행자에게 자선을 베풀 라 그것이 하나님의 기쁨을 얻 고자 하는 이들에게 가장 좋은 것 이라 그리하면 그들이 번영하리라`]},"is-51-19":{e:`quranenc-korean-rwwad`,t:[`그들의 재산에는, 구걸하는 자와 없는 자를 위한 몫이 있었노라.`]},"is-70-24-25":{e:`quranenc-korean-rwwad`,t:[`그들의 재산에 일정한 몫이 있는 자들이니`,`구걸하는 자와 없는 자를 위함이라.`]},"is-57-18":{e:`quranenc-korean-rwwad`,t:[`자선을 베푸는 남성들과 자신을 베푸는 여성들과 하나님을 위해 돌려받지 않을 빚을 내주는 자들, 그들을 위해 그것(보상)은 불어날 것이며 그들에게는 풍성한 보상이 있을 것이라.`]},"is-49-12":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 대부분의 추측을 피하라. 실로 어떤 추측은 죄가 되노라. 또한 그대들은 염탐하지 말고 서로가 서로를 험담하지 말라. 그대들 중에서 죽은 형제의 살코기를 먹고 싶어하는 자가 있단 말인가? 실로 그대들은 그것을 혐오할 것이라. 하나님을 경외하라. 실로 하나님께서는 뉘우치는 자를 받아 주는 자애로우신 분이라.`]},"is-23-3":{e:`quranenc-korean-hamid`,t:[`헛된 말을 하지 않는 자들이 며`]},"is-57-20":{e:`quranenc-korean-rwwad`,t:[`현세의 삶이란 한낱 놀음과 오락과 치장과 그대들간의 상호 과시와 재산과 자식을 더 많이 갖기 위한 경쟁에 불과함을 알라. (현세의 삶은) 해갈의 비와도 같으니, 불신자들은 그것(비)의 작물이 마음에 들었건만 그 후 그것(작물)은 말라붙어 버렸노라. 그리하여 그대는 그것이 누렇게 변함을 보며 그 후 그것은 부서진 조각이 되었노라. 내세에는 혹독한 벌과 하나님으로부터의 용서와 기쁨이 있노라. 현세의 삶이란 그저 허망한 유희일 뿐이라.`]},"is-18-28":{e:`quranenc-korean-hamid`,t:[`그러므로 아침과 저녁으로 주님께 강구하는 자들과 그대의 영혼을 같이하되 아름다운 현세의 삶을 원하여 그대의 눈이 그들을 간과하지 않도록 할 것이며 하나 님을 염원하지 아니하고 자신의 욕구만을 추구하는 자를 따르지 말라 그의 경우는 모든 범주를 벗 어난 것이라`]},"is-2-188":{e:`quranenc-korean-rwwad`,t:[`그대들은 그대들끼리 그대들의 재산을 부조리하게 취하지 말며, 죄됨을 알면서도 사람들 재산의 일부를 삼키기 위해 통치자에게 그것(재산)을 퍼 나르지 말라.`]},"is-5-87":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님께서 그대들을 위해 허락하신 좋고 깨끗한 것을 금하지 말며 경계를 넘어서지 말라. 실로 하나님께서는 경계를 넘어서는 자들을 사랑하지 않으시노라.`]},"is-4-148":{e:`quranenc-korean-rwwad`,t:[`하나님께서는 나쁜 말을 드러냄을 사랑하지 않으시나 부당히 대우받은 자는 예외라. 하나님께서는 들으시고 아시는 분이도다.`]},"is-2-168":{e:`quranenc-korean-rwwad`,t:[`사람들이여! 대지에 있는 것들 중에서 허락된 좋은 것을 먹되 사탄의 발자국을 따르지 말라. 실로 그는 그대들의 분명한 적이라.`]},"is-6-152":{e:`quranenc-korean-rwwad`,t:[`그리고 고아가 왕성한 기력에 이를 때까지 그의 재산에 가까이 다가가지 말지나, 더 훌륭한 것으로 그러할 때는 예외라. 공정으로써 부피와 무게를 확실히 재라. 나는 영혼에게 오직 감당할 수 있는 능력만큼만 짐 지우노라. 그대들이 (증언을) 말할 때는 그가 친척일지라도 공평을 기하라. 그리고 하나님의 계약을 준수하라. 이것이야말로 그분께서 그대들에게 분부하시는 것이니 그대들이 깊이 생각하게 될 것이라. ​`]},"is-4-58":{e:`quranenc-korean-rwwad`,t:[`실로 하나님께서는 그대들에게 명령하시니, 주인에게 ​수탁물을 되돌려 주고 사람들 사이를 판결할 때는 공평히 판결하라. 실로 하나님께서 그대들에게 주시는 교훈은 참으로 훌륭하노라. 실로 하나님께서는 들으시고 보시는 분이도다.`]},"is-16-91":{e:`quranenc-korean-hamid`,t:[`너희가 약속한 하나님의 성 약을 수행하되 너희가 하나님을 증인으로 확증한 맹세를 깨뜨리지말라 하나님께서는 너희가 행하는모든 것을 알고 계시나라`]},"is-33-70":{e:`quranenc-korean-hamid`,t:[`믿는자들이여 하나님을 경외하라 그리고 올바른 말을 하라`]},"is-9-119":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님을 경외하고 정직한 자들과 함께하라.`]},"is-31-16":{e:`quranenc-korean-hamid`,t:[`나의 아들아 겨자씨 만큼이나 작은 것이라 할지라도 그것이 돌속에 있던 하늘위에 있던 깊은 땅속에 있던간에 하나님은 그것을들추어 내시거늘 실로 하나님은 세심히 아시는 분이시라`]},"is-4-135":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님을 위한 증인으로서 공정함을 온전히 실천하는 자들이 되어라. 그것이 그대들 자신과 부모님과 친척들에게 불리할지라도 마찬가지라. 그가 부유하건 가난하건 하나님께서는 그들보다 더 우선이시라. 그러니 그대들은 욕구를 좇지 말라, 그럴 경우 그대들은 편향될 것이라. 만약 그대들이 왜곡하거나 등을 돌린다면 실로 하나님께서는 그대들이 행하는 일에 밝으신 분이라.`]},"is-55-9":{e:`quranenc-korean-rwwad`,t:[`그대들은 공정으로써 정확히 무게를 재고 저울을 감소시키지 말라.`]},"is-12-18":{e:`quranenc-korean-rwwad`,t:[`그들은 그의 상의에 거짓 피를 묻혀 왔노라. 그(야곱)가 말하였노라. "그렇지 않노라. 너희 자신이 일을 꾸민 것이라. 그러나 인내는 아름답도다. 너희가 (거짓으로) 묘사함에 (내가) 도움을 요청할 분은 하나님이시라"`]},"is-16-96":{e:`quranenc-korean-hamid`,t:[`너희에게 있는 것은 사라지 나 하나님께 있는 것은 영원하노 라 하나님은 인내하는 이들에게 그들이 행하던 선행에 최선의 것 으로 보상하리라`]},"is-11-11":{e:`quranenc-korean-rwwad`,t:[`그러나 인내하고 선행을 실천하는 자들은 예외로서, 그들에게는 용서와 커다란 보상이 있을 것이라.`]},"is-41-35":{e:`quranenc-korean-rwwad`,t:[`오직 인내한 자들만이 그것(고귀한 성품)을 얻을 것이며, 오직 지대한 몫의 소유자만이 그것(고귀한 성품)을 얻을 것이라.`]},"is-90-17":{e:`quranenc-korean-rwwad`,t:[`그 후에 그가 (하나님과 사도를) 믿고, 서로에게 인내를 권유하며, 서로에게 자비를 권유하는 자들 중의 하나가 되었더라면`]},"is-12-90":{e:`quranenc-korean-rwwad`,t:[`그들이 말하였노라. "실로 당신이 정녕 요셉이란 말입니까?" 그가 말하였노라. "저는 요셉이며, 이는 제 아우입니다. 하나님께서는 진정 우리에게 은혜를 베푸셨습니다. 실로 (하나님을) 경외하고 인내하는 자가 있다면, 실로 하나님께서는 최선을 다하는 자들의 보상을 저버리지 않으십니다"`]},"is-33-35":{e:`quranenc-korean-hamid`,t:[`실로 무슬림 남녀에게 믿음 이 있는 남녀에게 순종하는 남녀 에게 진실한 남녀와 인내하는 남 녀에게 두려워하는 남녀와 자선을베푸는 남녀에게 단식을 행하는 남녀와 정조를 지키는 남녀에게 하나님을 염원하는 남녀에게 하나님은 관용과 크나큰 보상을 준비 하셨노라`]},"is-29-59":{e:`quranenc-korean-hamid`,t:[`이들은 믿음에 인내하고 그 들의 주님께 의지하는 자들이라`]},"is-59-23":{e:`quranenc-korean-rwwad`,t:[`그분은 하나님으로서 그분 이외에는 경배받을 존재가 없노라. 제왕, 성스러우신 분, 그 어떤 결점도 없으신 분, 안전을 주시는 분, 지켜보시는 분, 가장 존엄하신 분, 위압하시는 분, 홀로 위대하신 분. 그들이 감히 (그분께) 대등한 존재를 두다니, 하나님께서는 완벽하신 분이라!`]},"is-13-24":{e:`quranenc-korean-rwwad`,t:[`“그대들에게 평안이 깃들기를. 그대들이 인내한 대가라. 이 얼마나 훌륭한 궁극의 안식처인가"`]},"is-56-25-26":{e:`quranenc-korean-rwwad`,t:[`그들은 그곳에서 실없는 말을 듣지 않으며 죄스런 언행도 없노라.`,`오직 평안하시오, 평안하시오 라는 말 뿐이라.`]},"is-19-62":{e:`quranenc-korean-hamid`,t:[`그들은 그 안에서 잡담이 아 닌 평안의 인사를 들으며 그 안 에서 조석으로 그들의 일용할 양 식을 만끽하니라`]},"is-97-5":{e:`quranenc-korean-rwwad`,t:[`그때는 오직 평안함 뿐이니, 새벽빛이 뜰 때까지라.`]},"is-4-86":{e:`quranenc-korean-rwwad`,t:[`그대들이 인사를 받았다면 그것보다 더 훌륭한 것으로써 인사하거나 그것에 응답하라. 실로 하나님께서는 모든 것을 셈하시는 분이도다.`]},"is-24-27":{e:`quranenc-korean-hamid`,t:[`믿는자들이여 허락을 받고 그 집안 가족에 인사를 하기전까 지는 너희집이 아닌 어떠한 가정 도 들어가지 말라 그것이 너희에 게 복이 되리니 너희가 교훈으로 삼으라`]},"is-39-23":{e:`quranenc-korean-rwwad`,t:[`하나님께서는 가장 훌륭한 말씀을 서로 비슷하고 반복되는 (구절의) 성서로 내리셨노라. 그로 인해 하나님을 두려워하는 자들의 피부는 전율하며, 그 후 그들의 피부와 마음은 하나님을 떠올림으로 평정을 되찾노라. 이것이야말로 하나님의 인도이며, 그분께서는 이로써 원하시는 자를 인도하시노라. 그러나 하나님께서 방황시키시는 자라면 그를 위한 그 어떤 인도자도 없노라.`]},"is-6-17":{e:`quranenc-korean-rwwad`,t:[`만약 하나님께서 그대를 어려움으로 만지신다면 그분 이외에는 그것을 걷어내 줄 자가 없노라. 만약 하나님께서 그대를 좋은 것으로 만지신다면 그분께서는 모든 것이 가능한 분이시라.`]},"is-21-83-84":{e:`quranenc-korean-hamid`,t:[`욥을 상기하라 그는 주님께 강구하였노라 재앙으로 제가 괴롭나이다 당신은 가장 자비로우시고자애로우시니 은혜를 베풀어 주옵소서`,`하나님은 그의 간청에 답하 여 그가 처한 재앙을 거두고 그가 잃어버린 자손들을 다시 얻게 하 였으니 이는 그분의 은혜요 모든 종들을 위한 교훈이라`]},"is-26-80":{e:`quranenc-korean-hamid`,t:[`내가 병들었을 때 나를 치료하여 주시며`]},"is-28-13":{e:`quranenc-korean-hamid`,t:[`그리하여 하나님은 그를 그의 어머니에게로 돌려보내니 그녀의 눈은 기쁨으로 가득차고 그녀 는 슬퍼하지도 아니 하였으며 하 나님의 약속이 진리임을 알게 되 었더라 그러나 대다수는 알지 못 하였노라`]},"is-2-157":{e:`quranenc-korean-rwwad`,t:[`이들에게는 실로 그들 주님으로부터의 축복과 자비가 있을 것이며 이들이야말로 인도받은 자들이라.`]},"is-21-69":{e:`quranenc-korean-hamid`,t:[`하나님이 명령하사 불아 식 어라 그리고 아브라함을 안전케 하라 하였노라`]},"is-11-6":{e:`quranenc-korean-rwwad`,t:[`대지에서 살아 움직이는 생명체 모두에게는 하나님께서 정해주신 양식이 있으며 그분께서는 그것이 정착할 장소와 그것이 놓일 장소를 알고 계시노라. 모두는 분명한 성서에 (기록되어) 있노라.`]},"is-10-107":{e:`quranenc-korean-rwwad`,t:[`만일 하나님께서 그대를 어려움으로 만지신다면 그분 이외에는 그것을 걷어내 줄 자가 없노라. 만일 그분께서 그대에게 좋은 것을 원하신다면 그분의 은혜를 되돌려 놓을 자도 없노라. 그분께서는 당신의 종복들 중에서 원하시는 자에게 그것(은혜)를 내리시노라. 그리고 그분께서는 가장 너그러이 용서하시고 가장 자애로우신 분이시라.`]},"is-18-110":{e:`quranenc-korean-hamid`,t:[`일러가로되 실로 나는 너희들과 똑같은 한 인간이나 단지 신 은 단 한분 뿐이라는 계시가 내게 내렸을 뿐 주님을 만나고자 원하 는 자는 선을 행하고 주님을 경배 할 때에는 어느 무엇과도 비유하 지 말라 하셨느니자`]},"is-11-90":{e:`quranenc-korean-rwwad`,t:[`그대들의 주님께 용서를 구하고 그 후 그분께 참회하라. 실로 나의 주님께서는 자애로우시고 많이 사랑하시는 분이라`]},"is-7-23":{e:`quranenc-korean-rwwad`,t:[`그 둘이 말하였노라. “저희의 주님! 저희는 저희 자신을 부당히 다루었습니다. 당신께서 저희를 용서하시고 자비를 베풀지 않으신다면 진실로 저희는 손실자들 중의 하나가 될 것입니다”`]},"is-71-10-12":{e:`quranenc-korean-rwwad`,t:[`그리하여 제가 말하였습니다: ‘그대들은 그대들 주님에게 용서를 구하라. 실로 그분께서는 모든 것을 용서하시는 분이도다.`,`그리하면 그분께서 그대들에게 줄기찬 비를 보내주실 것이라.`,`그리고 그대들에게 재산과 자손을 늘려주실 것이며 그대들을 위해 정원을 두실 것이며 그대들을 위해 강을 두실 것이라.`]},"is-30-50":{e:`quranenc-korean-hamid`,t:[`그러나 하나님 은혜의 예증 을 보라 그분께서 죽은 대지를 어 떻게 생동케 하느뇨 그와 마찬가 지로 그분은 죽은자를 살게 하시 니 이는 그분께서 모든 일에 전지 전능하시기 때문이라`]},"is-35-2":{e:`quranenc-korean-hamid`,t:[`하나님께서 그분의 자비로 인류를 위해 보내신 그 은혜를 누 구도 제재할 수 없으며 또한 그분께서 제지하신 것을 누구도 자유 롭게 할 수 없나니 그분은 권능과지혜로 충만하심이라`]},"is-3-8":{e:`quranenc-korean-rwwad`,t:[`“저희의 주님! 당신께서 저희를 인도해 주셨으니 그 후에 저희의 마음을 어긋나게 하지 말아 주십시오. 그리고 저희에게 당신으로부터의 자비를 주십시오. 진실로 당신께서는 조건 없이 베푸는 분이십니다”`]},"is-18-10":{e:`quranenc-korean-hamid`,t:[`보라 젊은이들이 동굴로 은 신하여 말하길 주여 저희에게 당 신의 자비를 베풀어 주소서 그리 고 저희가 하는 일을 올바른 길로 인도하여 주소서 라고 하였더라`]},"is-17-34":{e:`quranenc-korean-hamid`,t:[`고아가 성년에 이를 때까지 더 나은 것이 아니거늘 고아의 재산에 가까이 하지 말라 그리고 계약을 이행하라 그 모든 계약에 대하여 질문을 받으리라`]},"is-24-61":{e:`quranenc-korean-hamid`,t:[`장님과 볼구자와 병자와 너 희가 너희 가정에서 또는 너희 아버지 가정에서 또는 어머니 집에 서 또는 형제의 집에서 또는 자매의 집에서 또는 아버지 형제의 집에서 또는 아버지 자매의 집에서 또는 어머니 형제의 집에서 또는 어머니 자매의 집에서 또는 열쇠 를 인수 받은 집에서 또는 너의 진실한 친구의 집에서 식사를 하 는 것은 허물이 아니라 또한 너희가 한자리에서 또는 각라 식사를 하는 것도 허물이 아니라 그러나 너희가 집을 들어갈 때면 서로가서로에게 하나님이 주신 축복의 인사를 하라 이렇게 하나님은 너희를 위해 말씀을 밝히셨나니 너희는 이해 하리라`]},"is-17-80":{e:`quranenc-korean-hamid`,t:[`일러가로되 주여 저로하여금진실의 문으로 들어가게 하여 주 소서 그와 마찬가지로 진실의 출 구로 나오게 하여 주시고 당신 가까이에서 승리의 권한을 부여하여 주소서`]},"is-14-24-25":{e:`quranenc-korean-hamid`,t:[`너희는 하나님께서 어떻게 비유하셨는지 알지 못하느뇨 훌륭한 한 마디의 말은 알찬 한 그루 의 나무와 같다고 했거늘 그 뿌 리는 단단하고 그 가지는 하늘로 향하니라 하셨더라`,`그 나무는 매 계절마다 열매를 맺으며 이는 주님의 허락이라 하셨더라 또 하나님은 백성에게 비유를 들어 말씀하셨으니 이는 그들에게 교훈이 되도록 하고자 하심이라`]},"is-16-14":{e:`quranenc-korean-hamid`,t:[`그분께서 바다를 두시매 너 희가 그로하여 신선한 생선을 먹 도록 하셨고 그로부터 너희가 걸 칠 장식품을 얻도록 하였으며 파 도를 일고 가는 배를 너희가 보 리니 이는 너희가 그분의 은혜를 강구하도록 함이라 너희는 감사하 게 되리라`]},"is-30-23":{e:`quranenc-korean-hamid`,t:[`밤에는 잠을 자게 하고 낮에는 그분의 은혜로부터 양식을 구 하게 함도 그분 예중의 하나이거 늘 실로 그 안에는 듣는 백성을 위한 예증이 있노라`]},"is-78-9-11":{e:`quranenc-korean-rwwad`,t:[`그대들의 잠을 단절의 시간으로 두었노라.`,`그리고 밤을 옷으로 두었고`,`낮을 생계로 두었노라.`]},"is-2-185":{e:`quranenc-korean-rwwad`,t:[`라마단 달은 꾸란이 내려진 달이라. 꾸란은 인류를 위한 길잡이이자 분명한 증거로서, 길잡이인 동시에 옳고 그름의 기준이라. 그러니 그대들 중 이 달에 임한 자는 단식을 하도록 하라. 그러나 병자이거나 장거리 이동 중일 때는 셈한 날수(단식을 깬 날수)만큼의 다른 날들이라. 하나님께서는 그대들에게 쉬움을 원하시며 그대들에게 어려움을 원치 않으시노라. 또한 그분께서는 그대들이 셈한 날수를 채우기를 원하시며, 그분께서 그대들을 인도해 주셨음에 그대들이 하나님의 위대함을 찬양하기를 원하시니 그대들은 감사하게 될 것이라.`]},"is-93-11":{e:`quranenc-korean-rwwad`,t:[`그대 주님의 은총에 관하여는 이야기하라.`]},"is-34-13":{e:`quranenc-korean-hamid`,t:[`그들은 그의 뜻에 따라 그 를 위해 일하매 궁전을 만들고 동 상을 만들고 연못 같은 대야를 만 들고 화로에 고정된 큰 솥을 만 들었노라 그러하매 다윗의 자손들아 일하며 감사하라 했거늘 내 종가운데는 감사하는 자가 적더라`]},"is-27-40":{e:`quranenc-korean-hamid`,t:[`성서의 지식이 풍부한 자가 말하길 당신이 눈깜짝 할 사이에 그것을 가져오겠습니다 바로 그때솔로몬은 그것이 자기곁에 있음을보고서 말하길 이것은 내 주님의 은혜로써 이는 내가 감사하고 있 는지 은혜를 망각하고 있는지 시 험하려 하심이라 누구든 감사하는자는 자신의 영혼에 감사하는 자 이며 은혜를 망각하는 자는 하나 님의 은혜를 거역하는 자이거늘 실로 나의 주님은 풍요와 자비로 충만하심이라`]},"is-36-71-73":{e:`quranenc-korean-rwwad`,t:[`내가 그들을 위해 내 손이 행한 것으로써 가축을 창조하였음을, 이에 그들이 그것(가축)을 통제하는 자들이 되었음을 그들은 알지 못한단 말인가?`,`또한 나는 그들을 위해 그것(가축)을 길들였으니, 그것 중의 일부는 그들의 탈 것이며 그것 중의 일부로부터는 그들이 먹거리를 취하노라.`,`그것(가축)에는 여러 효용과 마실 거리도 있노라. 그러니 그들은 감사하지 않겠는가?`]},"is-26-215":{e:`quranenc-korean-hamid`,t:[`믿는자 중에서 그대를 따르 는 자에게는 그대의 날개를 낮추라`]},"is-17-24":{e:`quranenc-korean-hamid`,t:[`부모에게 공손하고 날개를 낮추며 겸손하라 그리고 기도하라주여 두분에게 은혜를 베푸소서 그 두 분은 어려서부터 저를 양육하였나이다`]},"is-20-44":{e:`quranenc-korean-hamid`,t:[`그러나 그에게 친절하게 말하라 아마도 그는 경각심을 갖거 나 하나님을 두려워 할 수도 있느니라`]},"is-18-23-24":{e:`quranenc-korean-hamid`,t:[`분명 내가 내일 그것을 행하리라 말하지 말며`,`하나님의 뜻이라 하되 그대 가 잊었을 때는 주님을 염원하라 내가 바라보니 나의 주님께서 이 것보다 더 가까이 을바른 길로 인도하여 주실 것이라 말하라`]},"is-21-90":{e:`quranenc-korean-hamid`,t:[`그의 간청에 하나님이 응하 사 그에게 요한을 보냈고 그를 위해 그의 아내를 정상으로 하였 으니 이들은 선행을 실천함에 서 둘러 하며 기대와 두려움으로 하 나님에게 호소하고 하나님을 두 려워 하였더라`]},"is-19-58":{e:`quranenc-korean-hamid`,t:[`이들은 아담의 자손들 가운데 하나님께서 은혜를 베푼 예언자들이라 그 중에는 노아와 함께 방주에 오른 자가 있었고 아브라 함과 이스라엘 자손이 있으며 그 중에는 하나님이 옳은 길로 인도 한 자가 있으며 선택한 자가 있었노라 하나님의 말씀이 그들에게 계시되었을 때 그들은 부복하고 경배하여 눈물을 흘렸노라`]},"is-32-16":{e:`quranenc-korean-hamid`,t:[`그들의 손발은 그들의 침상을 멀리하고 두려움과 희망으로 그들의 주님을 부르며 우리가 그 들에게 베푼 양식으로 자선을 베 푸노라`]},"is-2-238":{e:`quranenc-korean-rwwad`,t:[`그대들은 여러 예배들과 중간 예배를 꾸준히 지키고, (예배 시에는) 하나님을 위해 부단히 복종하며 서 있으라.`]},"is-11-56":{e:`quranenc-korean-rwwad`,t:[`실로 나는 나의 주님이시자 그대들의 주님이신 하나님께 의탁하였노라. 생명체 중에 그분께서 앞머리 채를 잡고 계시지 않는 것은 없노라. 실로 나의 주님께서는 올곧은 길 위에 계시노라`]},"is-18-14":{e:`quranenc-korean-hamid`,t:[`하나님이 그들의 마음을 강 하게 하였으니 그들이 일어나 말하더라 우리의 주님은 천지의 주님이시니 우리는 결코 그분 외 에 다른 신을 섬기지 않으리라 우 리가 그랬다면 우리는 실로 과장 된 말을 지꺼렸을 뿐이라`]},"is-28-31":{e:`quranenc-korean-hamid`,t:[`너의 지팡이를 던져보라 하는 소리가 들렸더라 그때 그것이 마치 뱀처럼 움직이는 것을 보았 으매 뒤로 돌아보지 아니하니 모 세야 앞으로 나오라 그리고 두려 워 하지 말라 실로 너는 믿는자 중에 있노라`]},"is-33-39":{e:`quranenc-korean-hamid`,t:[`그들은 하나님의 말씀을 전 하고 그분을 공경하며 하나님 외 에는 어느것도 두려워 하지 아니 하였으니 하나님은 미리 아심으로충만하심이라`]},"is-25-58":{e:`quranenc-korean-hamid`,t:[`죽지 아니하시고 영원히 살아계시는 그분만을 의지하며 그분만 을 찬양하라 그분은 그분 종들의 모든 잘못을 아시고 계시노라`]},"is-27-79":{e:`quranenc-korean-hamid`,t:[`하나님께 의지하라 그대가 바로 분명한 진리의 길위에 있노 라`]},"is-64-13":{e:`quranenc-korean-rwwad`,t:[`하나님 그분 이외에는 경배받을 존재가 없노라. 믿는 자들은 오직 하나님께만 의탁하도록 하라.`]},"is-28-22":{e:`quranenc-korean-hamid`,t:[`그가 마드얀 땅을 향하여 가며 기원하길 주께서 평탄하고 옳은 길로 저를 인도하여 주소서`]},"is-12-92":{e:`quranenc-korean-rwwad`,t:[`그가 말하였노라. "오늘 그대들에게는 아무런 책망도 없습니다. 하나님께서 그대들을 용서하실 것이니, 그분께서는 자애를 베푸는 자들 중에서 가장 자애로우신 분이십니다"`]},"is-12-98":{e:`quranenc-korean-rwwad`,t:[`그가 말하였노라. "내가 장차 너희를 위해 나의 주님께 용서를 구하겠노라. 진실로 그분께서는 가장 너그러이 용서하시고 가장 자애로우신 분이라"`]},"is-110-3":{e:`quranenc-korean-rwwad`,t:[`그대는 그대 주님의 완벽한 영광을 드높이고 그분께 용서를 구하라. 진실로 그분께서는 뉘우치는 자를 받아 주시는 분이도다.`]},"is-7-151":{e:`quranenc-korean-rwwad`,t:[`그(모세)가 말하였노라. "주님! 저를 그리고 제 형을 용서해 주시고, 저희를 당신의 자비 안에 들게 하십시오. 당신께서는 자애를 베푸는 자들 중에서 가장 자애로우신 분이십니다"`]},"is-2-280":{e:`quranenc-korean-rwwad`,t:[`만약 어려움을 겪는 자가 있다면 형편이 나아질 때까지의 유예라. 그대들이 알고 있다면 그대들이 자선을 베푸는 것이 그대들에게 더 좋은 것이라.`]},"is-42-25":{e:`quranenc-korean-rwwad`,t:[`당신의 종복들로부터 참회를 받아 주시는 분이 그분이시며, 그분께서는 악행에 관하여 관용을 베푸시노라. 그리고 그분께서는 그대들이 행하는 일을 알고 계시노라.`]},"is-9-104":{e:`quranenc-korean-rwwad`,t:[`실로 하나님 그분께서 당신의 종복으로부터 참회를 받아 주시고 희사금을 수락하시며, 실로 하나님 그분께서는 참회하는 모든 이를 용서하시는 가장 자애로우신 분이심을 그들은 알지 못하는가?`]},"is-4-26":{e:`quranenc-korean-rwwad`,t:[`하나님께서 원하시니 그대들을 위해 분명히 설명하시고 그대들 이전에 있었던 자들의 전통으로 그대들을 인도하시며 그대들의 뉘우침을 받아 주시노라. 하나님께서는 지식을 가지신 지혜로운 분이시라.`]},"is-30-24":{e:`quranenc-korean-hamid`,t:[`공포와 희망을 갖도록 너희 들에게 번갯불을 보이심과 하늘로부터 비를 내리게 하여 불모지의 땅을 생동케 하심도 그분 예증의 하나이시니 실로 그 안에는 지혜 가 있는 백성을 위한 예증이 있노 라`]},"is-10-5":{e:`quranenc-korean-rwwad`,t:[`태양을 광채로, 달을 빛으로 두시고 그것(달)을 여러 단계로 조절하시어 그대들이 햇수와 계산법을 알도록 하신 분이 그분이시라. 하나님께서는 오직 진리로써 그것(하늘과 땅)을 창조하셨도다. 그분께서는 지식을 가진 사람들을 위해 징표들을 자세히 설명하시노라.`]},"is-67-3-4":{e:`quranenc-korean-rwwad`,t:[`그분께서는 일곱 개의 하늘을 층층이 창조하셨도다. 그대는 가장 자비로우신 분의 창조에서 그 어떤 엉성함도 보지 못하노라. 그러니 그대의 눈을 되돌려 보라: 그대는 그 어떤 균열이라도 볼 수 있는가?`,`그 후 그대의 눈을 거듭하여 되돌려 보라: 몽롱해진 눈이 침침해진 채 그대에게로 되돌아갈 것이라.`]},"is-38-29":{e:`quranenc-korean-rwwad`,t:[`내가 그대에게 내린 축복 가득한 성서는 그들이 그 징표들을 숙고하기 위함이며, 슬기를 지닌 자들이 깊이 생각하기 위함이라.`]},"is-12-111":{e:`quranenc-korean-rwwad`,t:[`실로 그들의 이야기에는 슬기를 지닌 자들을 위한 교훈이 있노라. 그것(꾸란)은 지어낸 말이 아니며, 오히려 그 이전의 것(성서들)에 대한 확증이자 모든 것의 자세한 설명이며, 믿는 사람들을 위한 인도이자 자비라.`]},"is-51-20-21":{e:`quranenc-korean-rwwad`,t:[`그리고 대지에는 굳건히 믿는 자를 위한 징표가 있으며`,`그대들 자신에게도 징표가 있도다. 그러니 그대들은 통찰하지 않겠는가?`]},"is-45-13":{e:`quranenc-korean-rwwad`,t:[`또한 그분께서는 그대들을 위해 (일곱) 하늘에 있는 것과 땅에 있는 것을 유용케 하셨으니 그 모든 것은 그분으로부터 비롯되었노라. 진실로 그 안에는 숙고하는 자들을 위한 징표들이 있노라.`]},"is-29-20":{e:`quranenc-korean-hamid`,t:[`대지 위를 여행하면서 하나님께서 태초에 어떻게 창조하셨으며 후기의 창조가 어떠한가를 보라 실로 하나님은 모든 일에 전지전능하심이라`]},"is-16-11":{e:`quranenc-korean-hamid`,t:[`그분은 그것 으로 하여 너희를 위해 곡식과 올리브와 종려나 무 열매와 포도와 모든 종류의 열 매를 생산하시니 실로 그 안에는 백성이 숙고해야할 예증이 있노라`]},"is-17-12":{e:`quranenc-korean-hamid`,t:[`하나님은 낮과 밤을 예증의표적으로 하여 밤의 표적은 어둡 게 하고 낮의 표적은 밝게 하였니니 이는 너희가 주님으로부터 은 혜를 구하도록 함이여 또한 햇수 의 계산과 셈의 학문을 알 수 있 게 하였노라 이처럼 하나님은 그 에게 모든 것을 설명하였노라`]},"is-2-267":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 그대들이 얻은 좋은 것들과 내가 그대들을 위해 대지에서 꺼낸 것의 일부로 베풀라. 그리고 그대들은 눈을 감지 않는 이상 취하지 않을 추하고 더러운 것으로 가까이 가 그것으로 베풀지 말라. 그대들은 하나님께서 풍족하신 분이며 영광되신 분임을 알라.`]},"is-2-272":{e:`quranenc-korean-rwwad`,t:[`그대가 그들의 인도를 책임져야 하는 것이 아니라. 그러나 하나님께서는 원하시는 자를 인도하시노라. 그대들이 재산으로써 베푼다면 그것은 그대들 자신을 위한 것이라. 그대들이 베푸는 것은 오직 하나님의 얼굴을 간구하기 위함이라. 그대들이 재산으로 베푼다면 그분께서 그대들에게 남김 없이 보상해주실 것이며 그대들은 부당히 대우받지 않을 것이라.`]},"is-4-8":{e:`quranenc-korean-rwwad`,t:[`친척 관계에 있는 자들과 고아들과 불우한 자들이 (유산)분배에 참석하였다면 그(유산) 일부로 그들에게 양식을 베풀고 그들에게 친절한 말을 하라.`]},"is-4-114":{e:`quranenc-korean-rwwad`,t:[`그들의 비밀스런 대화 대부분에는 좋은 것이 없노라. 그러나 자선이나 선행이나 사람들 사이의 조정을 명하는 자는 예외라. 하나님의 기쁨을 간구하면서 그것을 행하는 자가 있다면 나는 장차 그에게 위대한 보상을 줄 것이라.`]},"is-30-39":{e:`quranenc-korean-hamid`,t:[`타인의 재산으로 이익을 증 가시킨 것은 하나님 곁에서는 아 무런 증거도 될 수 없노라 그러나하나님의 기쁨을 구하기 위하여 이슬람세로 이익을 증가함은 여러배의 보상을 받게 되니라`]},"is-34-39":{e:`quranenc-korean-hamid`,t:[`일러가로되 나의 주님께서는 그분이 원하는 그분의 종에게 일 용할 양식을 풍성케 하여 주시고 또 제한도 하시나니 너희가 주님 을 위해 사용하는 어떤 것도 그분께서는 보상을 하시거늘 그분은 일용할 양식을 주시는 가장 훌륭 한 분이시라`]},"is-35-29-30":{e:`quranenc-korean-hamid`,t:[`하나님의 성서를 낭독하며 예배를 드리고 하나님이 그들에게베푼 양식으로 알게 모르게 자선 을 베푸는 자들은 불멸의 이익을 얻노라`,`하나님은 그들에게 충족한 보상을 하시며 그분의 은혜를 더 하여 주시니 실로 그분은 관대하 시며 응답하시는 분이시라`]},"is-92-5-7":{e:`quranenc-korean-rwwad`,t:[`(하나님을 위해) 베풀고 (그분을) 경외하며`,`훌륭한 것을 확신하는 자`,`나는 그가 쉬이 평이함을 얻도록 할 것이라.`]},"is-92-18-21":{e:`quranenc-korean-rwwad`,t:[`자신의 재산을 내주어 (죄로부터) 정화되는 자라.`,`그것(그의 자선)은 대갚음 받을 은총을 지닌 누군가를 위한 것이 아니며`,`오직 가장 지고하신 그의 주님의 얼굴을 간구하기 위함이라.`,`그는 정녕 기뻐하게 될 것이라.`]},"is-2-219":{e:`quranenc-korean-rwwad`,t:[`그들이 그대에게 술과 도박에 관하여 물으니, 말하라. “그것에는 커다란 죄가 있고 인간을 위한 효용이 있으나 그것의 죄가 그것의 효용보다 더 크도다” 그들이 그대에게 무엇으로 베풀어야 하는지 물으니, 말하라. “여분의 재산이라” 그렇게 하나님께서는 그대들을 위해 명백히 징표들을 드러내시니 그대들이 숙고하기 위함이라.`]},"is-2-197":{e:`quranenc-korean-rwwad`,t:[`대순례(의 기간)는 잘 알려진 달이라. 그때 대순례를 결심한 자는 성지순례시 외설스런 말과 일탈 행위와 논쟁이 금지되노라. 그대들이 선행을 행한다면 하나님께서는 알고 계시노라. 그리고 그대들은 여행길의 식량을 준비하라. 여행길의 가장 훌륭한 식량은 경외심이라. 슬기를 지닌 자들이여, 나를 경외하라.`]},"is-17-28":{e:`quranenc-korean-hamid`,t:[`주님으로부터 너희가 기대하는 은혜를 그들에게 줄 것이 없어그들로부터 등 돌림을 받는다 해 도 그들에게 친절히 말하라`]},"is-2-60":{e:`quranenc-korean-rwwad`,t:[`기억하라. 모세가 그의 백성들을 위해 물을 요청하였고 이에 내가 말하였노라. “그대의 지팡이로 바위를 치라” 그러니 그곳에서 열 두개의 샘이 솟아올랐고 각각의 사람들이 그들의 물 마실 곳을 알았노라. “그대들은 하나님의 양식으로 먹고 마시되, 지상에서 해악을 퍼뜨리면서 폐해를 끼치지 말라”`]},"is-26-183":{e:`quranenc-korean-hamid`,t:[`사람의 정당한 권리를 보류 하지 말며 지상에 해악을 퍼뜨리 지 말라`]},"is-6-120":{e:`quranenc-korean-rwwad`,t:[`그대들은 드러난 죄와 감춰진 죄를 그만두라. 실로 죄를 범하는 자들은 그들이 얻어 오던 것으로 곧 징벌을 받을 것이라.`]},"is-4-31":{e:`quranenc-korean-rwwad`,t:[`만약 그대들이 그대들에게 금지된 커다란 죄를 피한다면 그분께서는 그대들의 악행을 용서해 주실 것이며 그대들을 실로 명예로운 장소(천국)로 들게 하실 것이라.`]},"is-2-283":{e:`quranenc-korean-rwwad`,t:[`만약 그대들이 장거리 이동 중이고 서기를 구하지 못했다면 저당된 전당물이라. 그리고 만약 그대들 서로가 서로에게 안전함을 느낀다면 수탁 받은 자는 자신의 수탁물을 되돌려 주도록 하고 자신의 주님이신 하나님을 두려워하도록 하라. 그대들은 증언을 감추지 말라. 그것(증언)을 감추는 자 있다는 실로 그는 그의 마음이 죄지은 자라. 하나님께서는 그대들이 행하는 것을 알고 계시는 분이라.`]},"is-5-8":{e:`quranenc-korean-rwwad`,t:[`​믿는 자들이여! 하나님을 위해 온전히 실천하는 자들, 공정히 증언하는 자들이 되어라. 그리고 한 무리에 대한 미움 때문에 그대들이 공평을 기하지 않는 일이 없도록 하라. 공평하라, 그것이 경외심에 더 가까운 것이라. 그리고 하나님을 경외하라. 실로 하나님께서는 그대들이 행하는 일에 밝으신 분이라.`]},"is-11-85":{e:`quranenc-korean-rwwad`,t:[`나의 백성들이여. 공정을 기하여 되와 저울을 확실하게 재고, 사람들에게 그들의 물건을 깎아내리지 말며, 해악을 퍼뜨리면서 지상에 폐해를 끼치지 말라.`]},"is-9-105":{e:`quranenc-korean-rwwad`,t:[`그대(무함마드)는 말하라. "행하라. 하나님과 그분의 사도와 믿는 자들이 그대들의 행위를 볼 것이라. 그런 후 그대들은 보이지 않는 것과 보이는 것을 알고 계시는 분께로 되돌아가게 되니, 그분께서 그대들에게 그대들이 행하던 것을 알려주실 것이라"`]},"is-3-76":{e:`quranenc-korean-rwwad`,t:[`그렇지 않노라. 자신의 계약을 준수하고 하나님을 경외하는 자가 있다면 실로 하나님께서는 경외하는 자들을 사랑하시노라.`]},"is-13-20":{e:`quranenc-korean-rwwad`,t:[`그들은 하나님의 서약을 이행하고 굳은 약속을 파기하지 않는 자들이라.`]},"is-16-90":{e:`quranenc-korean-hamid`,t:[`하나님께서 정의와 선을 실 천하라 명령하사 친척에게는 자 선을 베풀라 하셨으되 추한 언행 과 사악함과 배반함을 금하심으로너희에게 교훈으로 하셨노라`]},"is-8-27":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님과 사도를 배반하지 말고, 알면서도 그대들의 책무를 배반하지 말라.`]},"is-4-85":{e:`quranenc-korean-rwwad`,t:[`좋은 중재를 하는 자는 그에게 ​그 일부의 몫이 있을 것이며, 나쁜 중재를 하는 자는 그에게 ​그 일부의 몫이 있을 것이라. 하나님께서는 모든 것을 살피시는 분이도다.`]},"is-40-55":{e:`quranenc-korean-rwwad`,t:[`그러니 그대(무함마드)는 인내하라. 실로 하나님의 약속은 진리라. 그대는 그대의 죄에 관하여 (하나님께) 용서를 구하고, 저녁과 아침에 그대 주님의 완벽한 영광을 드높이라.`]},"is-12-83":{e:`quranenc-korean-rwwad`,t:[`그가 말하였노라. "그렇지 않노라. 너희 자신이 일을 꾸민 것이라. 그러나 인내는 아름답도다. 하나님께서 그들 모두를 내게로 데려와 주실지도 모르는 일이라. 진실로 그분께서는 모든 것을 알고 계시는 가장 지혜로우신 분이라"`]},"is-7-128":{e:`quranenc-korean-rwwad`,t:[`모세가 그의 백성에게 말하였노라. "하나님께 도움을 요청하고 인내하라. 실로 대지는 하나님의 소유로서 당신의 종복 중 원하시는 자에게 물려주시노라. (훌륭한) 결말은 (하나님을) 경외하는 자들에게 있노라.`]},"is-74-7":{e:`quranenc-korean-rwwad`,t:[`그대 주님을 위해 인내하라.`]},"is-28-54":{e:`quranenc-korean-hamid`,t:[`그들은 두배의 보상을 받으 리니 이는 그들이 인내하였고 악 을 선으로 이겨냈으며 하나님이 그들에게 준 양식을 자선으로 베 풀었기 때문이라`]},"is-11-49":{e:`quranenc-korean-rwwad`,t:[`이것은 내가 그대에게 계시하는 보이지 않는 소식의 일부라. 이 이전에는 실로 그대 뿐만이 아니라 그대의 백성들조차도 그것(소식)을 알지 못하고 있었노라. 그러니 그대는 인내하라. 실로 (훌륭한) 결말은 (하나님을) 경외하는 자들에게 있노라.`]},"is-20-132":{e:`quranenc-korean-hamid`,t:[`그대의 백성들이 예배를 드리고 그것에 인내하도록 하라 하 나님은 그 양식을 구하지 아니하 고 양식을 베푸노라 내세의 열매 는 경건한 자를 위한 것이라`]},"is-19-65":{e:`quranenc-korean-hamid`,t:[`천지에 있는 것과 그 사이에 있는 것이 주님의 것이거늘 그분 을 섬김에 있어 그분과 동등한 다 른 것을 알고 있느뇨`]},"is-30-21":{e:`quranenc-korean-hamid`,t:[`너희 자신들로 부터 배필을 창조하여 그 배필과 함께 살게 하심도 그분 예증의 하나이며 그분 은 또한 너희간에 사랑과 자비를 주셨으니 실로 그 안에는 생각하 는 백성을 위한 예증이 있노라`]},"is-73-8":{e:`quranenc-korean-rwwad`,t:[`그대는 그대 주님의 이름을 떠올리고 오로지 그분께로 전념하라.`]},"is-76-25-26":{e:`quranenc-korean-rwwad`,t:[`그리고 이른 낮과 늦은 낮에 그대 주님의 이름을 떠올리며`,`밤중에는 그분을 위해 부복하고 밤의 오랜 시간에 그분을 찬양하라.`]},"is-29-45":{e:`quranenc-korean-hamid`,t:[`그대에게 계시된 그 성서를 낭송하며 예배를 드리라 예배는 수치와 그릇된 행위를 예방하여 주리라 그리고 하나님을 염원하는 것은 생활의 가장 중요한 것으로 의심할 바 없나니 하나님은 너희가행하는 모든 것을 알고 계시노라`]},"is-17-78":{e:`quranenc-korean-hamid`,t:[`서산에 해가 기울어 어둠이 질 때까지 예배를 올리고 새벽에 도 꾸란을 낭송하라 진실로 새벽 의 꾸란 낭송은 천사가 지켜보니 라`]},"is-16-80":{e:`quranenc-korean-hamid`,t:[`하나님께서 너희에게 집을 주어 그곳에서 기거하게 하사 가 축의 가죽으로는 천막을 주어 여 행과 정착함에 짐을 털어주시고 가축의 털로서는 얼마동안 생활 필수품으로 유용케 하셨노라`]},"is-10-67":{e:`quranenc-korean-rwwad`,t:[`그대들을 위해 밤을 두시어 그대들이 그 안에서 편안함을 찾도록 하고, 낮은 시각의 제공자로 하신 분이 그분이시라. 진실로 그 안에는 듣는 자를 위한 징표들이 있노라.`]},"is-20-14":{e:`quranenc-korean-hamid`,t:[`실로 내가 하나님이요 나 외에는 신이 없나니 나만을 경배하 고 예배하며 나만을 생각하라`]},"is-11-120":{e:`quranenc-korean-rwwad`,t:[`내가 그대에게 들려주는 사도들의 모든 소식은 내가 그것으로 그대의 마음을 굳건히 하는 것이라. 그리고 그대에게 이(장(章)) 안에서 진리와 가르침과 믿는 자들을 위한 떠올림이 도래하였노라.`]},"is-20-2-3":{e:`quranenc-korean-hamid`,t:[`하나님이 그대에게 꾸란을 계시함은 그것으로 하여 그대를 고 생되게 하려함이 아니라`,`하나님을 두려워하는 이들을 위한 교훈이 되게 했노라`]},"is-64-11":{e:`quranenc-korean-rwwad`,t:[`그 어떤 시련도 하나님의 허락 없이는 일어나지 않노라. 하나님을 믿는 자가 있다면 그분께서는 그의 마음을 인도하실 것이라. 하나님께서는 모든 것을 알고 계신 분이라.`]},"is-27-62":{e:`quranenc-korean-hamid`,t:[`필요한자가 부를 때 이에 대답하시는 분이 누구이시며 사악을제거하여주사 그대들을 대지위의 후계자로 하여주신 분이 누구이뇨하나님 외에 다른 신이 있을 수 있느뇨 그런데도 너희는 숙고하지않느뇨`]},"is-19-4":{e:`quranenc-korean-hamid`,t:[`그가 말하길 주여 저의 뼈들 은 허약하여지고 머리는 백발이 되었나이다 저는 주님께 기원하여축복받지 아니한 적이 없었습니다`]},"is-19-25-26":{e:`quranenc-korean-hamid`,t:[`종려나무 줄기를 네가 있는 쪽으로 혼들어라 그러면 잘 익은 열매가 너에게로 떨어지리니`,`먹고 마시어 마음을 평안케 하라 그리고 네가 사람을 만나거 든 저는 하나님께 단식할 것을 맹세하였으매 오늘 누구와도 말을하지 않을 것이라 말하여라`]},"is-4-28":{e:`quranenc-korean-rwwad`,t:[`하나님께서는 그대들을 위하여 (부담을) 경감시키길 원하시니, 인간은 나약하게 창조되었노라.`]},"is-33-43":{e:`quranenc-korean-hamid`,t:[`그분과 천사들은 너희에게 축복을 주시니 너희를 암혹에서 광명으로 인도하심이라 실로 그분은 믿음을 가진 자들에게 자비로 우셨노라`]},"is-17-20":{e:`quranenc-korean-hamid`,t:[`하나님은 이들에게도 그리고저들에게도 보상을 주리라 그대 주님의 보상은 제한됨이 없노라`]},"is-57-21":{e:`quranenc-korean-rwwad`,t:[`그대들은 그대들 주님으로부터의 용서와 천국을 위해 경쟁하라. 그 너비는 하늘과 땅의 너비와 같으며 하나님과 그분의 사도들을 믿는 자들을 위해 준비되었노라. 이는 하나님의 은혜로서 그분께서 원하시는 자에게 주시노라. 하나님께서는 지대한 은혜의 소유자시라.`]},"is-24-35":{e:`quranenc-korean-hamid`,t:[`하나님은 하늘과 땅의 빛이 라 그 빛을 비유하사 벽위의 등잔과 같은 것으로 그 안에 등불 이 있으며 그 등불은 유리안에 있더라 그 유리는 축복받은 올리 브 기름으로 별처럼 밝게 빛나도 다 그것은 동쪽에 있는 나무도 아 니요 서쪽에 있는 나무도 아니라 그 기름은 불이 닿지도 아니하나 더욱 빛나 빛위에 빛을 터하도다 하나님은 그분이 원하는자를 그 빛으로 인도하시며 사람들 위에 예증을 보이시니 하나님은 모든 것을 아심으로 충만하시노라`]},"is-55-60":{e:`quranenc-korean-rwwad`,t:[`최선에 대한 보상은 오직 최선일 뿐이라.`]},"is-25-74":{e:`quranenc-korean-hamid`,t:[`기뻐할 수 있는 아내와 자손들을 주옵소서 그리고 저희들이 정직한 사람들의 모범이 되도록 하여 주옵소서 라고 말하는 자들 이라`]},"is-14-40":{e:`quranenc-korean-hamid`,t:[`주여 저로 하여금 예배를 드리는 자가 되게하여 주소서 저의 자손에게도 그렇게 하여 주소서 주여 그리고 기도를 받아 주소서`]},"is-3-38":{e:`quranenc-korean-rwwad`,t:[`거기서 자카리야가 그의 주님께 기도하니 “저의 주님! 당신으로부터 비롯된 좋은 후손을 저에게 주십시오. 실로 당신께서는 기도를 들으시는 분입니다”`]},"is-26-83-84":{e:`quranenc-korean-hamid`,t:[`주여 저에게 지혜를 주옵시 고 의로운 사람 가운데 있게 하여 주소서`,`다음 세대에서 제가 의로운 자로 입에 오르도록 하여 주소서`]},"is-6-160":{e:`quranenc-korean-rwwad`,t:[`​(심판의 날) 하나의 선을 가져온 자가 있다면 그는 그것과 유사한 것의 열 배를 가질 것이라. 그러나 하나의 악을 가져온 자가 있다면 그가 받을 징벌은 오직 그것과 유사한 것 뿐이라. 그들은 부당히 다루어지지 않노라.`]},"is-1-2-5":{e:`quranenc-korean-rwwad`,t:[`모든 찬미는 만유의 주님이신 하나님의 것이라.`,`가장 자비로우시고 가장 자애로우신 분.`,`심판의 날의 집권자.`,`저희는 당신만을 경배하며 당신께만 도움을 요청합니다.`]},"is-16-68-69":{e:`quranenc-korean-hamid`,t:[`그대의 주님께서 은혜를 부 여하사 벌에게 산과 나무와 사람 이 사는 거주지에 집을 지으라 하시고`,`모든 꽃에서 일용할 양식을먹되 주님의 길을 따르라 이는 쉬우니라 하셨더라 그들 몸에서는 여러가지 색깔의 마실것이 나오며인간에게 유용한 치료약이 있으니실로 그 안에는 숙고하는 백성을 위한 예증이 있노라`]},"is-50-9-10":{e:`quranenc-korean-rwwad`,t:[`그리고 나는 하늘에서 축복 가득한 비를 내리어 그것으로써 정원과 수확될 곡물을 자라나게 하였노라.`,`또한 높이 뻗은 야자수를 자라게 하니 그것에진 겹쳐진 꽃밥이 있도다.`]},"is-80-24-27":{e:`quranenc-korean-rwwad`,t:[`그러니 인간은 그의 먹거리를 보도록 하라.`,`실로 나는 비를 퍼부었고`,`그런 후 대지를 갈라내어`,`그 안에서 곡물을 자라나게 하였으며`]},"is-55-10-12":{e:`quranenc-korean-rwwad`,t:[`대지는 그분께서 놓으셨으니 생명체를 위함이라.`,`거기에는 과일과, 포엽을 지닌 야자수가 있고`,`깍지를 지닌 곡물과, 바질이 있더라.`]},"is-14-32-33":{e:`quranenc-korean-hamid`,t:[`하나님께서 천지를 창조하사하늘에서 비를 내리게 하셨으며 그로부터 열매를 맺게하여 너희에게 일용할 양식으로 하였노라 또 한 너희를 위해 우주를 주관하시 매 그분의 명령에 따라 바다를 운행케 하고 강이 너희에게 유용케 하셨더라`,`그분은 해와 달이 항상 그 운행을 지키게 하여 너희에게 유 용케 하시며 밤과 낮을 너희에게 유용케 하시니라`]},"is-26-78-79":{e:`quranenc-korean-hamid`,t:[`그분은 나를 창조하셨고 또 나를 인도하시며`,`그분은 나에게 일용할 양식 을 주시고 마실 음료수를 주시며`]},"is-16-5-7":{e:`quranenc-korean-hamid`,t:[`너희를 위해 가축들을 창조 하셨으니 그 안에는 온기가 있어 유용하며 또한 그것으로 일용할 양식을 섭취하도다`,`너희가 그 가축들을 집으로 데려올 때와 목장으로 안내하는 그 안에는 너희를 위한 아름다움 이 있으며`,`너희가 수고 없이는 먼 지역 까지 운반할 수 없는 무거운 짐을 가축들이 운반하여 주나니 실로 주님은 사랑과 자비로 충만하심이라`]},"is-106-3-4":{e:`quranenc-korean-rwwad`,t:[`그러니 그들(꾸레이쉬 부족)은 이 (카으바) 성전의 주님을 경배토록 하라.`,`그분께서는 배고픔이 사라지도록 그들에게 음식을 주시고, 두려움이 사라지도록 그들에게 안전을 주신 분이라.`]},"is-20-53-54":{e:`quranenc-korean-hamid`,t:[`그분께서는 당신들을 위해 대지를 요람으로 하였으며 그 안 에 길을 주시었노라 또한 하나님 은 하늘로부터 비를 내리게 하여 그것으로 하여 여러가지 초목을 싹트게 하였노라`,`그것을 일용한 양식으로 섭 취하고 그리고 너희들의 가축을 길러라 실로 지혜가 있는 자를 위한 예중이 그 안에 있노라`]},"is-25-61":{e:`quranenc-korean-hamid`,t:[`하늘에 성좌를 배치하시고 그 안에 큰 등불을 두셨으며 등 불과 같은 달을 두신 그분께 축복 이 충만하소서`]},"is-32-7":{e:`quranenc-korean-hamid`,t:[`하나님은 그분이 창조하신 모든 것을 가장 조화있게 두셨으며 인간을 흙에서 창조하기 시작하 셨노라`]},"is-49-3":{e:`quranenc-korean-rwwad`,t:[`실로 하나님의 사도 앞에서 자신의 목소리를 낮추는 자들, 그들은 경외심을 얻도록 하나님께서 그들의 마음을 순화해 주신 자들이라. 그들에게는 용서와 위대한 보상이 있을 것이라.`]},"is-26-217-219":{e:`quranenc-korean-hamid`,t:[`전능과 자비로 충만하신 분 에게 의지하라`,`그분은 예배하기 위해 홀로 서 있는 그대를 보고 계시며`,`그대가 엎드려 예배하는 자 들 중에 있을 때도 보고 계시나니`]},"is-33-21":{e:`quranenc-korean-hamid`,t:[`진실로 너희에게 하나님께서 보내신 선지자의 훌륭한 모범이 있었거늘 이는 하나님과 내세와 하나님을 염원하는 것을 원하는 자를 위해서라`]},"is-2-32":{e:`quranenc-korean-rwwad`,t:[`그들이 말하였노라. “완벽하신 당신이십니다! 당신께서 우리에게 가르쳐 주신 것 이외에는 우리에게 어떠한 지식도 없나이다. 진실로 당신께서는 모든 것을 알고 계시는 가장 현명하신 분입니다”`]},"is-18-39":{e:`quranenc-korean-hamid`,t:[`네가 너의 과수원에 들어갔 을 때 내가 너보다 가난하고 네가재산과 자손으로 나보다 강함을 보았더라도 하나님의 뜻이 있으리라 하나님 외에는 권능이 없다고 말하지 아니 하였더뇨`]},"is-17-84":{e:`quranenc-korean-hamid`,t:[`일러가로되 모든 인간은 자 기 스스로의 방법에 따라 행동하 려 하거늘 그러나 주님은 누가 가장 옳은 길로 인도되는가를 아심 이라`]},"is-17-70":{e:`quranenc-korean-hamid`,t:[`하나님은 아담의 자손에게 은혜를 베풀어 육지와 바다에서 그들을 운반하여 주고 그들에게 좋은 양식을 부여하여 하나님이 창조한 어떤 것보다 그들을 위에 두었노라`]},"is-2-127":{e:`quranenc-korean-rwwad`,t:[`아브라함과 이스마엘이 (카으바) 성전의 토대를 올리니 “저희의 주님! 저희를 받아 주십시오. 실로 당신께서는 모든 것을 들으시는 분이시며 모든 것을 알고 계신 분이십니다”`]},"is-11-123":{e:`quranenc-korean-rwwad`,t:[`(일곱) 하늘과 땅의 보이지 않는 것이 하나님의 소유이며, 그 모든 일은 그분께로 돌아가게 되노라. 그러니 그대는 그분을 경배하고 그분께 의탁하라. 그대의 주님께서는 그대들이 하는 일에 부주의한 분이 아니시라.`]},"is-9-129":{e:`quranenc-korean-rwwad`,t:[`그럼에도 그들이 돌아선다면 그대(무함마드)는 말하라. "나는 하나님만으로 충분하며 그분 이외에는 경배받을 존재가 없노라. 나는 오직 그분께만 의탁하였으며 그분께서는 위대한 권좌의 주님이시라"`]},"is-28-35":{e:`quranenc-korean-hamid`,t:[`하나님께서 웅답하사 우리가너의 팔을 튼튼하게 하리라 또한 우리는 형제를 통하여 너희 둘을 권능케 하리니 그들이 너희를 대 적하지 못하리라 우리의 예증으로써 너희 두 형제와 너희를 따르는자가 승리할 것이라`]},"is-3-104":{e:`quranenc-korean-rwwad`,t:[`그대들 중 한 무리가 있도록 하여 그들이 좋은 것으로 (사람들을) 초대하며 선을 권하고 악을 금하도록 하라. 이들이야말로 성공한 자들이라.`]},"is-2-148":{e:`quranenc-korean-rwwad`,t:[`모두에게는 그가 지향하는 방향이 있노라. 그러니 그대들은 선행을 위해 경쟁하라. 그대들이 어디에 있든 하나님께서는 그대들 모두를 데려오실 것이라. 실로 하나님께서는 모든 것이 가능한 분이시라.`]},"is-25-71":{e:`quranenc-korean-hamid`,t:[`회개하고 선을 행하는 자가 진실로 하나님께 회개하는 자이며`]},"is-57-28":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님을 경외하고 그분의 사도를 믿으라. 그리하면 그분께서는 당신의 자비로써 그대들에게 갑절의 몫을 주실 것이며 그대들을 위해 광명을 두실 것이니 그대들은 그것으로써 걸어나갈 것이며, 그분께서는 그대들을 용서하여 주실 것이라. 하나님께서는 너그러이 용서하시는 자애로우신 분이라.`]},"is-59-10":{e:`quranenc-korean-rwwad`,t:[`그리고 (공물 전리품은) 그들 이후에 온 자들의 것으로, 그들이 말하더라. “저희의 주님! 저희를 용서하여 주시고, 신앙심으로써 저희를 앞서간 저희의 형제들을 용서하여 주십시오. 그리고 저희의 마음속에 믿는 자들에 대한 미움을 두지 말아 주십시오. 저희의 주님! 실로 당신은 인자하시고 자애로우신 분입니다”`]},"is-23-118":{e:`quranenc-korean-hamid`,t:[`일러가로되 주여 용서하여 주시고 자비를 베풀어 주소서 당 신이야말로 은혜를 베푸는 가장 훌륭한 분이시옵니다`]},"is-16-12-13":{e:`quranenc-korean-hamid`,t:[`그분은 밤과 낮을 너희를 위해 교차하게 하사 태양과 달과 별들이 그분의 명령에 복종케 하 니 실로 그 안에는 백성이 알아야 할 예증이 있노라`,`대지위에 창조한 모든 것들 을 여러 색깔로 하여 너희에게 유용케 하였으니 실로 그 안에는 백성이 염원해야 할 교훈이 있노 라`]},"is-13-2-3":{e:`quranenc-korean-rwwad`,t:[`그대들이 보는 어떤 기둥도 없이 (일곱) 하늘을 올리시고, 그 후 권좌 위로 오르신 분이 하나님이시라. 그분께서 해와 달을 복종시키셨으니, 각자는 지정된 기한을 향해 운행하고 있노라. 그분께서는 모든 일을 관장하시고 징표들을 자세히 설명하시니, 그대들이 그대들 주님과의 만남을 굳건히 믿기 위함이라.`,`대지를 펼치시고 그 안에 단단한 산과 강을 두시며 그 안에 온갖 열매로부터 한 쌍의 암수를 두신 분이 그분이시라. 그분께서는 밤이 낮을 덮게 하시노라. 진실로 그 안에는 숙고하는 사람들을 위한 징표들이 있노라.`]},"is-6-99":{e:`quranenc-korean-rwwad`,t:[`​하늘에서 비를 내리신 분이 그분이시라. 그리하여 나는 그것으로써 모든 종류의 식물을 내었고, 그로부터 푸르른 것을 내었으며, 그로부터 알이 촘촘한 곡물을 내었노라. 그리고 야자수에는 그 꽃밥에서 나온 드리워진 열매가지들이 있으며, 나는 포도 정원과 올리브와 석류를 내니, 비슷하고 서로 비슷하지 않더라. 그대들은 그것이 열매를 맺을 때 그 열매와 그 여물음을 보라. 진실로 그 안에는 믿는 자들을 위한 징표가 있노라.`]},"is-10-6":{e:`quranenc-korean-rwwad`,t:[`진실로, 밤과 낮의 교체와 하나님께서 (일곱) 하늘과 땅 안에 창조한 것들에는 하나님을 경외하는 자들을 위한 징표들이 있노라.`]},"is-36-38-40":{e:`quranenc-korean-rwwad`,t:[`태양은 자신을 위한 정착지를 향해 운행하노라. 이것이야말로 가장 존엄하시고 모든 것을 알고 계신 분의 섭리라.`,`그리고 달은 내가 그것의 단계를 조절하였으니 결국 그것은 마치 오래된 대추야자의 다발처럼 그렇게 돌아가노라.`,`태양이 달을 따라잡는 것은 그것(태양)에 적합하지 않으며, 밤은 낮을 앞서가지 않노라. 모두는 궤도 안에서 순항하노라.`]},"is-21-33":{e:`quranenc-korean-hamid`,t:[`그분께서 밤과 낮 태양과 달을 창조하시니 모든 것이 그 안에서 궤도에 따라 운행하노라`]},"is-31-27":{e:`quranenc-korean-hamid`,t:[`지상에 있는 모든 수목이 연필이 되고 일곱개의 바다를 더하 여 물로 가득찬 바다가 잉크가 된다 하더라도 하나님 말씀 모두를 기륵 할 수는 없나니 실로 하나님온 권능과 지혜로 충만하심이라`]},"is-6-59":{e:`quranenc-korean-rwwad`,t:[`그분께는 보이지 않는 것의 열쇠가 있으며, 오직 그분만이 그것(열쇠)을 아시노라. 그리고 그분께서는 육지와 바다에 있는 것을 알고 계시니, 그 어떤 낙엽이 떨어지든 그분께서는 어김없이 그것을 알고 계시노라. 대지의 어둠 속 낟알도, 촉촉한 것이든 메마른 것이든 항상 그것은 분명한 성서에 (기록되어) 있노라.`]},"is-30-20":{e:`quranenc-korean-hamid`,t:[`너희가 흙에서 창조되어 인 간으로서 번성하게 됨도 그분의 예증의 하나라`]},"is-55-1-4":{e:`quranenc-korean-rwwad`,t:[`가장 자비로우신 분.`,`그분께서는 꾸란을 가르쳐 주셨고`,`인간을 창조하셨으며`,`그에게 표현하는 법을 가르쳐 주셨노라.`]},"is-71-15-16":{e:`quranenc-korean-rwwad`,t:[`하나님께서 어떻게 일곱 개의 하늘을 층층이 창조하셨는지 그대들은 알지 못하는가?`,`그분께서는 달을 그(하늘) 안에 빛으로 두셨으며 태양을 등불로 두셨노라.`]},"is-90-14-16":{e:`quranenc-korean-rwwad`,t:[`허기진 날에 (사람들에게) 음식을 베풀고`,`친척 관계의 고아나`,`도탄에 빠진 불우한 자에게 음식을 베푸는 것이라.`]},"is-64-17":{e:`quranenc-korean-rwwad`,t:[`그대들이 하나님을 위해 돌려받지 않을 빚을 내준다면 그분께서는 그대들을 위해 그것을 불려 주실 것이며 그대들을 용서해 주실 것이라. 하나님께서는 풍성히 보답하시는 분이며 관대히 용인하시는 분이라. 요약주해`]},"is-2-265":{e:`quranenc-korean-rwwad`,t:[`하나님의 기쁨을 간구하며 자아로부터의 확신으로써 자신의 재산을 베푸는 자들의 예는 언덕에 있는 정원과도 같으니 그것이 장대비를 맞아 그 열매를 두 배로 가져다 주더라. 그러나 그것이 장대비를 맞지 않을 때는 구슬비라. 하나님께서는 그대들이 행하는 것을 보고 계시는 분이라.`]},"is-2-3":{e:`quranenc-korean-rwwad`,t:[`그들은 보이지 않는 것을 믿고 성실히 예배를 드리며 내가 그들에게 제공한 양식으로 베푸노라.`]},"is-8-3":{e:`quranenc-korean-rwwad`,t:[`그들은 성실히 예배를 드리고, 내가 그들에게 제공한 양식으로써 베푸노라.`]},"is-9-71":{e:`quranenc-korean-rwwad`,t:[`믿는 남성들과 믿는 여성들은 서로가 서로의 보호자라. 그들은 선을 명하고 악을 금하며, 성실히 예배를 드리고 의무 희사금(자카)을 내며 하나님과 그분의 사도를 따르노라. 이들은 하나님께서 곧 자비를 베푸실 자들이라. 실로 하나님께서는 존엄하시고 지혜로우신 분이라.`]},"is-42-38":{e:`quranenc-korean-rwwad`,t:[`그리고 그들은 자신들의 주님의 부름에 답하고 성실히 예배를 드리노라. 그들의 사안은 그들 사이의 자문(으로 결정되)며, 그들은 내가 그들에게 제공한 양식으로써 베푸노라.`]},"is-63-9":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 그대들의 재산과 그대들의 자식들이 하나님을 떠올림에 방해가 되지 않도록 하라. 그렇게 하는 자, 저들은 실로 손실자들이라.`]},"is-40-39":{e:`quranenc-korean-rwwad`,t:[`나의 사람들이여. 이 현세에서의 삶은 그저 유희일 뿐입니다. 그리고 실로 내세, 그것이야말로 영원의 거주지입니다`]},"is-4-32":{e:`quranenc-korean-rwwad`,t:[`그대들은 하나님께서 그대들 중 일부에게만 더해 베푸신 것을 탐내지 말라. 남성에게는 그들이 얻은 몫이 있으며 여성에게는 그들이 얻은 몫이 있노라. 그대들은 하나님께 그분의 은혜를 구하라. 실로 하나님께서는 모든 것을 알고 계신 분이도다.`]},"is-7-26":{e:`quranenc-korean-rwwad`,t:[`아담의 자손들이여. 실로 나는 그대들에게 그대들의 부끄러운 부분을 가려 주는 옷과 아름다운 의상을 내렸노라. 그러나 경외심의 옷, 그것이 더 좋으니라. 이것은 하나님의 징표 중의 일부이니 그들이 깊이 생각하기 위함이라.​`]},"is-42-36":{e:`quranenc-korean-rwwad`,t:[`그러하니, 그대들이 받은 그 어떤 것일지라도 (그것은) 현세 삶에서의 유희에 불과하노라. 그러나 (하나님을) 믿고 오직 그들의 주님께만 의탁하는 자들에게는 하나님께서 가지고 계신 것들이 더 훌륭하고 더 오래 남는 것이라.`]},"is-64-15":{e:`quranenc-korean-rwwad`,t:[`그대들의 재산과 자식들은 시험일 뿐이라. 위대한 보상은 하나님 그분께 있노라.`]},"is-91-9-10":{e:`quranenc-korean-rwwad`,t:[`그것(영혼)을 정화한 자는 진정 성공하였으며`,`그것(영혼)을 은폐한 자는 진정 실패하였도다.`]},"is-70-32-33":{e:`quranenc-korean-rwwad`,t:[`그리고 그들은 실로 그들의 수탁물과 계약을 중요하시는 자들이라.`,`그리고 그들은 실로 굳건히 그들의 증언을 서는 자들이라.`]},"is-4-9":{e:`quranenc-korean-rwwad`,t:[`그들은 두려워하도록 하라: 만약 그들이 그들 뒤에 허약한 후손을 남겼더라면 그들(후손)을 걱정했을 것이라. 그러니 그들은 하나님을 경외하도록 하고 적절한 말을 하도록 하라.`]},"is-28-26":{e:`quranenc-korean-hamid`,t:[`두 여인 중 한 여인이 말하 길 아버지 그를 고용하소서 그는 아버지께서 고용하고자 한 가장 훌륭한 자 중에 한 사람으로 힘이 세고 믿을 수 있는 사람입니다`]},"is-12-55":{e:`quranenc-korean-rwwad`,t:[`그(요셉)가 말하였노라. "저를 이 땅의 곳간을 관리하는 자로 임명하십시오. 실로 저는 빈틈없이 지키는 자이자 지식을 갖춘 자입니다"`]},"is-55-7-9":{e:`quranenc-korean-rwwad`,t:[`하늘은 그분께서 높이셨으며, 그분께서는 저울을 놓으셨으니`,`그대들이 저울의 경계를 넘어서지 않도록 함이라.`,`그대들은 공정으로써 정확히 무게를 재고 저울을 감소시키지 말라.`]},"is-59-18":{e:`quranenc-korean-rwwad`,t:[`믿는 자들이여! 하나님을 두려워하고 자신이 내일(심판의 날) 무엇을 내놓을 것인지 보도록 하라. 그대들은 하나님을 경외하라. 실로 하나님께서는 그대들이 행하는 일에 밝으신 분이라.`]},"is-23-51":{e:`quranenc-korean-hamid`,t:[`선지자들이여 허락된 좋은 것들을 섭취하되 선을 행하라 너 희가 행하는 일들을 내가 알고 있노라`]},"is-21-85":{e:`quranenc-korean-hamid`,t:[`이스마엘과 이드리스와 줄키 플에 관한 이야기를 그대의 백성 에게 상기시키라 그들 모두는 인 내하는 자 중에 있었노라`]},"is-18-69":{e:`quranenc-korean-hamid`,t:[`그가 하나님의 뜻이라면 인 내하고 내가 당신을 거역하지 아 니함을 알게 되리요`]},"is-29-2-3":{e:`quranenc-korean-hamid`,t:[`우리는 믿나이다 라고만 말하면 시험을 받지 아니한다고 사람 들을 생각하느뇨`,`하나님은 이미 이전의 사람들도 시험하였으니 하나님께서는 진실을 말하는 자와 거짓을 말하는 자들을 아시니라`]},"is-57-4":{e:`quranenc-korean-rwwad`,t:[`하늘과 땅을 엿새 만에 창조하신 후 권좌 위로 오르신 분이 그분이시라. 그분께서는 대지로 들어가는 것과 그로부터 나오는 것과 하늘에서 내려오는 것과 그 안으로 올라가는 것을 알고 계시노라. 그분께서는 그대들이 어디에 있든 그대들과 함께 계시노라. 그리고 하나님께서는 그대들이 행하는 것을 보고 계시는 분이라.`]},"is-2-255":{e:`quranenc-korean-rwwad`,t:[`하나님, 살아계신 분이며 모든 것을 주관하시는 그분 이외에는 경배받을 존재가 없노라. 졸음도 잠도 그분에게 다가가지 못하노라. 하늘에 있는 것과 대지에 있는 것이 그분의 소유라. 그분 앞에서 그분의 허락 없이 중재할 수 있는 자 누구인가. 그분께서는 그들 앞에 있는 것과 그들 뒤에 있는 것을 알고 계시노라. 그들은 그분의 지식에 관해 그 어떤 것도 아우르지 못하나 그분께서 뜻하시는 것은 예외라. 그분의 쿠르시(의자)는 하늘과 땅을 포괄하며 그분은 그 모두(하늘과 땅)를 보호하심에 피곤함을 느끼지 않으시노라. 그분께서는 지고하시고 위엄하신 분이라.`]},"is-4-1":{e:`quranenc-korean-rwwad`,t:[`사람들이여! 한 인간(아담)으로부터 그대들을 창조하셨고 그(아담)로부터 그의 배우자를 창조하셨으며 그 둘로부터 많은 남성과 여성을 퍼뜨리신 그대들의 주님을 두려워하라. 그대들이 서로에게 요구하면서 맹세하는 하나님을 두려워하고 친척(관계의 단절)을 두려워하라. 실로 하나님께서는 그대들에 대해 모든 것을 감시하시는 분이도다.`]},"is-87-14-15":{e:`quranenc-korean-rwwad`,t:[`진정 성공한 자는 정화된 자이며`,`자신의 주님의 이름을 떠올린 후 예배를 드린 자라.`]},"is-2-110":{e:`quranenc-korean-rwwad`,t:[`그대들은 성실히 예배를 드리고 의무 희사금(자카)을 내라. 그대들 자신을 위해 내놓는 그 어떤 재산도 그대들은 하나님 앞에서 그것을 발견할 것이라. 실로 하나님께서는 그대들이 행하는 것을 보고 계시는 분이라.`]},"is-12-64":{e:`quranenc-korean-rwwad`,t:[`그가 말하였노라. "내가 이전에 너희에게 그의 형을 맡겼던 것처럼 그렇게 너희에게 그를 맡기란 말인가? 그러나 하나님이야말로 지키심에 으뜸이신 분이며, 그분께서는 자애를 베푸는 자들 중에서 가장 자애로우신 분이시라"`]},"is-9-128":{e:`quranenc-korean-rwwad`,t:[`그대들에게 그대들 출신의 사도가 도래하였으니 (그는) 그대들이 고생함을 안쓰러워 하고, 그대들을 보살피며, 믿는 자들에게 인자하고 자애로우니라.`]},"is-21-89":{e:`quranenc-korean-hamid`,t:[`자카리야의 이야기를 상기시킬지니 그는 주님께 구원하였노라주여 저를 홀로 두지 마옵소서 당신은 가장 훌륭하신 상속자이십니다`]},"is-22-65":{e:`quranenc-korean-hamid`,t:[`하나님께서 대지위의 모든 것과 그분의 명령으로 바다를 다 니는 배들로 하여금 너희에게 복 종케 하셨음을 너희는 알지 못하 느뇨 그분의 허락 없이는 비가 땅에 내리지 못하도록 하시었노라 실로 하나님은 사람들에게 친절하시고 자비로우시니라`]},"is-57-22":{e:`quranenc-korean-rwwad`,t:[`대지에서나 그대 자신들에게 닥친 모든 시련은 내가 그것(시련)을 만들어내기 이전에 (이미) 성서에 (기록되어) 있노라. 이것은 실로 하나님께는 손쉬운 일이라.`]},"is-67-19":{e:`quranenc-korean-rwwad`,t:[`그들은 그들 위에서 날개를 펼치고 접는 새를 보지 않았던가? 오직 가장 자비로우신 분만이 그것(새)을 붙잡아 주시노라. 실로 그분께서는 모든 것을 보시는 분이라.`]},"is-5-9":{e:`quranenc-korean-rwwad`,t:[`(하나님과 사도를) 믿고 선행을 실천하는 자들에게 하나님께서 약속하시니 그들에게는 용서와 위대한 보상이 있을 것이라.`]},"is-2-128":{e:`quranenc-korean-rwwad`,t:[`“저희의 주님! 저희를 당신께 순종하는 자로, 그리고 저희의 후손들의 일부를 당신께 순종하는 공동체로 만들어 주십시오. 또한 저희에게 저희의 경배 방식을 보여주시고 저희의 뉘우침을 받아 주십시오. 진실로 당신께서는 뉘우치는 모든 이를 용서하시는 가장 자애로우신 분입니다”`]},"is-11-61":{e:`quranenc-korean-rwwad`,t:[`싸무드 부족에게는 그들의 형제인 쌀리흐(를 보냈노라). 그가 말하였노라. "나의 백성들이여, 하나님을 경배하라. 그분 이외에는 그대들이 경배할 존재가 없노라. 그분께서는 흙으로부터 그대들을 만드셨고 그곳에서 그대들이 정착하도록 하셨노라. 그러니 그분께 용서를 구하고 그 후 그분께로 참회하라. 실로 나의 주님께서는 가까이 계시고 응답하시는 분이라”`]},"is-4-40":{e:`quranenc-korean-rwwad`,t:[`실로 하나님께서는 티끌의 무게라도 부당히 다루지 않으시노라. 만약 그것이 선행이라면 그분께서는 그것을 불려주실 것이며 그분으로부터 비롯된 위대한 보상을 주실 것이라.`]},"is-95-4":{e:`quranenc-korean-rwwad`,t:[`진실로 나는 인간을 가장 훌륭한 체계로 창조하였노라.`]}};export{e as default};